import React from 'react';
import { Card, CardHeader, CardContent, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';

export default function FundCard({ fund, categoryName }) {
  // Progress bar: balance vs monthly_amount (if monthly_amount > 0)
  const progress = fund.monthly_amount > 0 ? Math.min(100, Math.round((fund.balance / fund.monthly_amount) * 100)) : null;
  return (
    <Card className="border-l-4 border-l-yellow-500 dark:bg-gray-800">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <CardTitle className="text-sm text-gray-700 dark:text-gray-200 flex items-center gap-2">
          {fund.fund_name}
          {categoryName && categoryName !== '-' && (
            <Badge className="ml-2 bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200" size="sm">{categoryName}</Badge>
          )}
        </CardTitle>
        <span className={`text-xs font-semibold ${fund.is_active ? 'text-green-600 dark:text-green-400' : 'text-gray-400'}`}>{fund.is_active ? 'Active' : 'Inactive'}</span>
      </CardHeader>
      <CardContent>
        <div className="mb-2">
          <span className="text-2xl font-bold text-amber-600 dark:text-amber-300">Rp {Number(fund.balance || 0).toLocaleString('id-ID', { maximumFractionDigits: 0 })}</span>
        </div>
        <div className="flex items-center justify-between mb-1">
          <span className="text-xs text-gray-500">Alokasi per bulan:</span>
          <span className="text-xs font-semibold text-gray-700 dark:text-gray-200">Rp {Number(fund.monthly_amount || 0).toLocaleString('id-ID', { maximumFractionDigits: 0 })}</span>
        </div>
        {progress !== null && (
          <div className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden mb-1">
            <div
              className="h-2 bg-amber-500 dark:bg-amber-400"
              style={{ width: `${progress}%` }}
            />
          </div>
        )}
        {progress !== null && (
          <div className="flex justify-between text-xs text-gray-400">
            <span>0%</span>
            <span>{progress}%</span>
            <span>100%</span>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
