import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { API_BASE_URL } from '../../config/api';
import {
  DollarSign, TrendingUp, TrendingDown, Plus, Pencil, Trash2,
  RefreshCw, Wallet, BarChart3, ChevronLeft, ChevronRight
} from 'lucide-react';

const PAGE_SIZE = 15;

const PaginationBar = ({ list, page, setPage }) => {
  const total = list.length;
  const totalPages = Math.ceil(total / PAGE_SIZE);
  if (totalPages <= 1) return null;

  const start = (page - 1) * PAGE_SIZE + 1;
  const end = Math.min(page * PAGE_SIZE, total);

  const go = (p) => setPage(Math.max(1, Math.min(p, totalPages)));

  const pages = [];
  const delta = 2;
  const left = Math.max(1, page - delta);
  const right = Math.min(totalPages, page + delta);
  for (let i = left; i <= right; i++) pages.push(i);

  return (
    <div className="px-4 py-3 border-t border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
      <span className="text-sm text-gray-500 dark:text-gray-400">
        {start}–{end} dari {total} transaksi
      </span>
      <div className="flex items-center gap-1">
        <button
          onClick={() => go(page - 1)} disabled={page === 1}
          className="p-1.5 rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <ChevronLeft className="h-4 w-4 text-gray-600 dark:text-gray-400" />
        </button>

        {left > 1 && (
          <>
            <button onClick={() => go(1)} className="w-8 h-8 text-sm rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400">1</button>
            {left > 2 && <span className="px-1 text-gray-400 text-sm">…</span>}
          </>
        )}

        {pages.map(p => (
          <button key={p} onClick={() => go(p)}
            className={`w-8 h-8 text-sm rounded-md font-medium transition-colors ${
              p === page ? 'bg-[#ed6f5c] text-white' : 'hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
            }`}
          >{p}</button>
        ))}

        {right < totalPages && (
          <>
            {right < totalPages - 1 && <span className="px-1 text-gray-400 text-sm">…</span>}
            <button onClick={() => go(totalPages)} className="w-8 h-8 text-sm rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400">{totalPages}</button>
          </>
        )}

        <button
          onClick={() => go(page + 1)} disabled={page === totalPages}
          className="p-1.5 rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <ChevronRight className="h-4 w-4 text-gray-600 dark:text-gray-400" />
        </button>
      </div>
    </div>
  );
};
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';

const KeuanganRW = () => {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const [summary, setSummary] = useState(null);
  const [kasRT, setKasRT] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [form, setForm] = useState({ tipe: 'pemasukan', kategori: '', deskripsi: '', jumlah: '', tanggal: '' });
  const [saving, setSaving] = useState(false);
  const [pageRW, setPageRW] = useState(1);
  const [pageRT, setPageRT] = useState(1);

  useEffect(() => { fetchAll(); }, [token, rtId]);

  const fetchAll = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = rtId ? { rt_id: rtId } : {};
      const [sumRes, rtRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/rw/finance/summary`, { headers, params }),
        axios.get(`${API_BASE_URL}/api/rw/finance/kas-rt`, { headers, params }),
      ]);
      setSummary(sumRes.data);
      setKasRT(rtRes.data);
      setPageRW(1);
      setPageRT(1);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (val) =>
    new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(val || 0);

  const formatDate = (d) => d ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '-';

  const openAdd = () => {
    setEditItem(null);
    setForm({ tipe: 'pemasukan', kategori: '', deskripsi: '', jumlah: '', tanggal: new Date().toISOString().split('T')[0] });
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    setForm({
      tipe: item.tipe,
      kategori: item.kategori || '',
      deskripsi: item.deskripsi || '',
      jumlah: item.jumlah,
      tanggal: item.tanggal?.split('T')[0] || ''
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.jumlah || !form.tanggal) return;
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      const payload = { ...form, jumlah: parseFloat(form.jumlah) };
      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/rw/finance/kas-rw/${editItem.id}`, payload, { headers });
      } else {
        await axios.post(`${API_BASE_URL}/api/rw/finance/kas-rw`, payload, { headers });
      }
      setShowForm(false);
      fetchAll();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus transaksi ini?')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/rw/finance/kas-rw/${id}`, { headers });
      fetchAll();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data keuangan...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const s = summary?.summary || {};
  const kasRWList = summary?.kas_rw_transaksi || [];
  const rtList = kasRT?.recent_transaksi || [];

  const pagedRW = kasRWList.slice((pageRW - 1) * PAGE_SIZE, pageRW * PAGE_SIZE);
  const pagedRT = rtList.slice((pageRT - 1) * PAGE_SIZE, pageRT * PAGE_SIZE);

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Keuangan</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-green-500 to-emerald-600 rounded-xl flex items-center justify-center shadow">
            <DollarSign className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Keuangan RW</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Kas RW + Rekap Kas RT</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchAll} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button onClick={openAdd} className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors">
            <Plus className="h-4 w-4" />Tambah Kas RW
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Saldo RW', value: formatCurrency(s.saldo_rw), color: 'from-blue-500 to-indigo-600', icon: Wallet },
          { label: 'Saldo RT', value: formatCurrency(s.saldo_rt), color: 'from-green-500 to-emerald-600', icon: DollarSign },
          { label: 'Total Kas', value: formatCurrency(s.total_kas), color: 'from-purple-500 to-violet-600', icon: BarChart3 },
          { label: 'IPL Tunggakan', value: formatCurrency(summary?.ipl?.belum_bayar), color: 'from-red-500 to-rose-600', icon: TrendingDown },
        ].map((card, i) => (
          <div key={i} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
            <div className={`w-12 h-12 bg-gradient-to-br ${card.color} rounded-xl flex items-center justify-center`}>
              <card.icon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">{card.label}</p>
              <p className="text-lg font-bold text-gray-900 dark:text-white">{card.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <Tabs defaultValue="kas-rw">
        <TabsList className="bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700">
          <TabsTrigger value="kas-rw">Kas RW</TabsTrigger>
          <TabsTrigger value="kas-rt">Rekap Kas RT</TabsTrigger>
        </TabsList>

        {/* Kas RW Tab */}
        <TabsContent value="kas-rw">
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
            <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
              <div>
                <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Transaksi Kas RW</h3>
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  Saldo: <span className={s.saldo_rw >= 0 ? 'text-green-600 font-semibold' : 'text-red-600 font-semibold'}>
                    {formatCurrency(s.saldo_rw)}
                  </span>
                </p>
              </div>
            </div>
            {kasRWList.length > 0 ? (
              <>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Tanggal</TableHead>
                      <TableHead>Tipe</TableHead>
                      <TableHead>Kategori</TableHead>
                      <TableHead>Deskripsi</TableHead>
                      <TableHead className="text-right">Jumlah</TableHead>
                      <TableHead className="text-center">Aksi</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {pagedRW.map((k) => (
                      <TableRow key={k.id}>
                        <TableCell className="text-sm">{formatDate(k.tanggal)}</TableCell>
                        <TableCell>
                          <Badge variant="outline" className={k.tipe === 'pemasukan'
                            ? 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20'
                            : 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20'
                          }>
                            {k.tipe === 'pemasukan' ? <TrendingUp className="h-3 w-3 mr-1 inline" /> : <TrendingDown className="h-3 w-3 mr-1 inline" />}
                            {k.tipe}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-sm">{k.kategori || '-'}</TableCell>
                        <TableCell className="text-sm">{k.deskripsi || '-'}</TableCell>
                        <TableCell className={`text-right font-semibold ${k.tipe === 'pemasukan' ? 'text-green-600' : 'text-red-600'}`}>
                          {k.tipe === 'pengeluaran' ? '-' : '+'}{formatCurrency(k.jumlah)}
                        </TableCell>
                        <TableCell className="text-center">
                          <div className="flex items-center justify-center gap-1">
                            <button onClick={() => openEdit(k)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                              <Pencil className="h-3.5 w-3.5" />
                            </button>
                            <button onClick={() => handleDelete(k.id)} className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <PaginationBar list={kasRWList} page={pageRW} setPage={setPageRW} />
              </>
            ) : (
              <div className="text-center py-12">
                <DollarSign className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
                <p className="text-gray-500 dark:text-gray-400">Belum ada transaksi kas RW</p>
              </div>
            )}
          </div>
        </TabsContent>

        {/* Kas RT Tab */}
        <TabsContent value="kas-rt">
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
            <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
              <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Rekap Kas RT</h3>
              <div className="flex gap-6 mt-2 text-sm">
                <span className="text-gray-500 dark:text-gray-400">
                  Pemasukan: <span className="text-green-600 font-semibold">{formatCurrency(kasRT?.total_pemasukan)}</span>
                </span>
                <span className="text-gray-500 dark:text-gray-400">
                  Pengeluaran: <span className="text-red-600 font-semibold">{formatCurrency(kasRT?.total_pengeluaran)}</span>
                </span>
                <span className="text-gray-500 dark:text-gray-400">
                  Saldo: <span className={`font-semibold ${(kasRT?.saldo || 0) >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {formatCurrency(kasRT?.saldo)}
                  </span>
                </span>
              </div>
            </div>
            {rtList.length > 0 ? (
              <>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Tanggal</TableHead>
                      <TableHead>Tipe</TableHead>
                      <TableHead>Kategori</TableHead>
                      <TableHead>Deskripsi</TableHead>
                      <TableHead className="text-right">Jumlah</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {pagedRT.map((k) => (
                      <TableRow key={k.id}>
                        <TableCell className="text-sm">{formatDate(k.tanggal)}</TableCell>
                        <TableCell>
                          <Badge variant="outline" className={k.tipe === 'pemasukan'
                            ? 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20'
                            : 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20'
                          }>
                            {k.tipe === 'pemasukan' ? <TrendingUp className="h-3 w-3 mr-1 inline" /> : <TrendingDown className="h-3 w-3 mr-1 inline" />}
                            {k.tipe}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-sm">{k.kategori || '-'}</TableCell>
                        <TableCell className="text-sm">{k.deskripsi || '-'}</TableCell>
                        <TableCell className={`text-right font-semibold ${k.tipe === 'pemasukan' ? 'text-green-600' : 'text-red-600'}`}>
                          {formatCurrency(k.jumlah)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <PaginationBar list={rtList} page={pageRT} setPage={setPageRT} />
              </>
            ) : (
              <div className="text-center py-12">
                <p className="text-gray-500 dark:text-gray-400">Belum ada transaksi RT</p>
              </div>
            )}
          </div>
        </TabsContent>
      </Tabs>

      {/* Form Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-md">
          <DialogHeader>
            <DialogTitle>{editItem ? 'Edit Transaksi Kas RW' : 'Tambah Transaksi Kas RW'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label>Tipe</Label>
              <Select value={form.tipe} onValueChange={v => setForm(f => ({ ...f, tipe: v }))}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="pemasukan">Pemasukan</SelectItem>
                  <SelectItem value="pengeluaran">Pengeluaran</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Kategori</Label>
              <Input className="mt-1" placeholder="Contoh: Iuran, Operasional..." value={form.kategori} onChange={e => setForm(f => ({ ...f, kategori: e.target.value }))} />
            </div>
            <div>
              <Label>Deskripsi</Label>
              <Input className="mt-1" placeholder="Keterangan transaksi..." value={form.deskripsi} onChange={e => setForm(f => ({ ...f, deskripsi: e.target.value }))} />
            </div>
            <div>
              <Label>Jumlah (Rp)</Label>
              <Input className="mt-1" type="number" placeholder="0" value={form.jumlah} onChange={e => setForm(f => ({ ...f, jumlah: e.target.value }))} />
            </div>
            <div>
              <Label>Tanggal</Label>
              <Input className="mt-1" type="date" value={form.tanggal} onChange={e => setForm(f => ({ ...f, tanggal: e.target.value }))} />
            </div>
          </div>
          <DialogFooter>
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-800">
              Batal
            </button>
            <button onClick={handleSave} disabled={saving} className="px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default KeuanganRW;
