import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
} from "@/components/ui/alert-dialog";
import { Trash2 } from "lucide-react";

export default function RolesPage() {
  const { token, user } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);
  const [roles, setRoles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [newRoleName, setNewRoleName] = useState("");
  const [newRoleDesc, setNewRoleDesc] = useState("");
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  // Admin dapat selalu membuat dan menghapus role
  const isAdmin = user?.role === 'admin';
  const canCreateRole = isAdmin || canCreate('management-roles');
  const canDeleteRole = isAdmin || canDelete('management-roles');

  // Load roles
  useEffect(() => {
    if (token) {
      loadRoles();
    }
  }, [token]);

  const loadRoles = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/roles`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const data = await res.json();
      setRoles(data);
    } catch (err) {
      console.error("Gagal load roles", err);
      toast.error("Gagal memuat daftar role");
    }
  };

  // Create new role
  const handleCreateRole = async () => {
    if (!newRoleName.trim()) {
      toast.error("Nama role tidak boleh kosong");
      return;
    }

    setLoading(true);

    try {
      const res = await fetch(`${API_BASE_URL}/api/roles`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: newRoleName.trim(),
          description: newRoleDesc,
        }),
      });

      if (res.ok) {
        toast.success("Role berhasil dibuat");
        setNewRoleName("");
        setNewRoleDesc("");
        loadRoles();
      } else {
        const err = await res.json();
        toast.error(err.detail || "Gagal membuat role");
      }
    } catch (err) {
      console.error("Error creating role", err);
      toast.error("Gagal membuat role");
    } finally {
      setLoading(false);
    }
  };

  // Delete role
  const handleDeleteRole = async (roleId) => {
    setLoading(true);

    try {
      const res = await fetch(`${API_BASE_URL}/api/roles/${roleId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        toast.success("Role berhasil dihapus");
        loadRoles();
        setDeleteConfirm(null);
      } else {
        const err = await res.json();
        toast.error(err.detail || "Gagal menghapus role");
      }
    } catch (err) {
      console.error("Error deleting role", err);
      toast.error("Gagal menghapus role");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div>
        <h1 className="text-3xl font-bold dark:text-gray-100">Manajemen Role</h1>
        <p className="text-sm text-gray-600 dark:text-gray-400">
          Kelola role/peran untuk pengguna sistem
        </p>
      </div>

      {/* CREATE ROLE FORM */}
      {canCreateRole && (
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <h2 className="font-semibold text-lg dark:text-gray-100">
            Buat Role Baru
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">
                Nama Role
              </label>
              <Input
                placeholder="Contoh: supervisor"
                value={newRoleName}
                onChange={(e) => setNewRoleName(e.target.value)}
                disabled={loading}
                className="mt-2 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
              />
            </div>

            <div>
              <label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">
                Deskripsi
              </label>
              <Input
                placeholder="Deskripsi role"
                value={newRoleDesc}
                onChange={(e) => setNewRoleDesc(e.target.value)}
                disabled={loading}
                className="mt-2 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
              />
            </div>

            <div className="flex items-end">
              <Button
                onClick={handleCreateRole}
                disabled={loading}
                className="w-full bg-green-500 hover:bg-green-600 text-white"
              >
                {loading ? "Membuat..." : "Buat Role"}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* ROLES LIST */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700">
        <h2 className="font-semibold text-lg dark:text-gray-100 mb-4">
          Daftar Role ({roles.length})
        </h2>

        {roles.length === 0 ? (
          <p className="text-gray-600 dark:text-gray-400">Tidak ada role</p>
        ) : (
          <div className="space-y-2">
            {roles.map((role) => (
              <div
                key={role.id}
                className="flex items-center justify-between p-4 bg-[#ece4cf] dark:bg-gray-800 rounded-lg border dark:border-gray-700"
              >
                <div className="flex-1">
                  <p className="font-medium dark:text-gray-100">{role.name}</p>
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    {role.description || "-"}
                  </p>
                </div>

                {canDeleteRole && (
                  <Button
                    size="sm"
                    variant="destructive"
                    onClick={() => setDeleteConfirm(role.id)}
                    disabled={["admin"].includes(role.name)}
                    className="ml-4"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Role?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => handleDeleteRole(deleteConfirm)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
