import { useEffect, useState } from "react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { Trash2 } from "lucide-react";

export default function TransaksiBatalIPL() {
  const [batalList, setBatalList] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [selectedBatal, setSelectedBatal] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const { token } = useAuth();

  // Format currency for display
  const formatCurrency = (value) => {
    if (!value) return "Rp 0";
    return `Rp ${value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".")}`;
  };

  // Format date
  const formatDate = (dateStr) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString("id-ID", {
      year: "numeric",
      month: "short",
      day: "2-digit",
    });
  };

  // Get month name
  const getMonthName = (bulan) => {
    const months = [
      "Januari", "Februari", "Maret", "April", "Mei", "Juni",
      "Juli", "Agustus", "September", "Oktober", "November", "Desember"
    ];
    return months[bulan - 1] || "";
  };

  const loadBatalList = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/ipl/transaksi-batal`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setBatalList(data);
    } catch (err) {
      console.error("Error loading transaksi batal:", err);
      toast.error("Gagal memuat data transaksi batal");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteBatal = (batal) => {
    setSelectedBatal(batal);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/ipl/transaksi-batal/${selectedBatal.id}`,
        {
          method: "DELETE",
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (res.ok) {
        toast.success("Transaksi batal berhasil dihapus");
        loadBatalList();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menghapus transaksi batal");
      }
    } catch (err) {
      console.error("Error deleting transaksi batal:", err);
      toast.error("Gagal menghapus transaksi batal");
    } finally {
      setShowDeleteConfirm(false);
      setSelectedBatal(null);
    }
  };

  // Search filter
  const filtered = batalList.filter((item) =>
    item.blok_no?.toLowerCase().includes(search.toLowerCase()) ||
    item.pemilik_sah?.toLowerCase().includes(search.toLowerCase())
  );

  // Pagination
  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const start = (currentPage - 1) * itemsPerPage;
  const paginatedData = filtered.slice(start, start + itemsPerPage);

  useEffect(() => {
    loadBatalList();
  }, []);

  return (
    <div className="space-y-6">
      {/* HEADER */}
      <div>
        <h2 className="text-2xl font-bold dark:text-gray-100">Transaksi Batal IPL</h2>
        <p className="text-sm text-gray-600 dark:text-gray-400">
          Riwayat pembatalan transaksi pembayaran IPL dengan alasan
        </p>
      </div>

      {/* SEARCH */}
      <div className="flex gap-4">
        <Input
          placeholder="Cari blok rumah atau nama pemilik..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
          className="max-w-md dark:bg-gray-800 dark:border-gray-700"
        />
      </div>

      {/* TABLE */}
      <div className="border rounded-lg dark:border-gray-700 overflow-hidden">
        <Table>
          <TableHeader className="bg-[#ece4cf] dark:bg-gray-800">
            <TableRow className="border-b dark:border-gray-700">
              <TableHead className="dark:text-gray-200">Blok</TableHead>
              <TableHead className="dark:text-gray-200">Pemilik</TableHead>
              <TableHead className="dark:text-gray-200">Periode</TableHead>
              <TableHead className="dark:text-gray-200">Nominal</TableHead>
              <TableHead className="dark:text-gray-200">Alasan Batal</TableHead>
              <TableHead className="dark:text-gray-200">Dibatalkan Oleh</TableHead>
              <TableHead className="dark:text-gray-200">Tanggal Batal</TableHead>
              <TableHead className="text-right dark:text-gray-200">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan="8" className="text-center py-8 text-gray-500">
                  Memuat data...
                </TableCell>
              </TableRow>
            ) : paginatedData.length === 0 ? (
              <TableRow>
                <TableCell colSpan="8" className="text-center py-8 text-gray-500">
                  Tidak ada transaksi batal
                </TableCell>
              </TableRow>
            ) : (
              paginatedData.map((item) => (
                <TableRow key={item.id} className="border-b dark:border-gray-700 hover:bg-[#e4dcc8] dark:hover:bg-gray-800">
                  <TableCell className="font-semibold dark:text-gray-200">{item.blok_no}</TableCell>
                  <TableCell className="dark:text-gray-300">{item.pemilik_sah}</TableCell>
                  <TableCell className="dark:text-gray-300">
                    {getMonthName(item.bulan)} {item.tahun}
                  </TableCell>
                  <TableCell className="font-semibold text-red-600 dark:text-red-400">
                    {formatCurrency(item.jumlah)}
                  </TableCell>
                  <TableCell className="dark:text-gray-300 max-w-xs truncate">
                    {item.alasan_batal}
                  </TableCell>
                  <TableCell className="dark:text-gray-300">{item.dibatalkan_oleh || "-"}</TableCell>
                  <TableCell className="dark:text-gray-300">{formatDate(item.created_at)}</TableCell>
                  <TableCell className="text-right">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleDeleteBatal(item)}
                      className="text-red-600 hover:text-red-800 hover:bg-red-50 dark:text-red-400 dark:hover:bg-gray-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* PAGINATION */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Halaman {currentPage} dari {totalPages} ({filtered.length} total)
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
              disabled={currentPage === 1}
              className="dark:border-gray-700"
            >
              Sebelumnya
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
              disabled={currentPage === totalPages}
              className="dark:border-gray-700"
            >
              Selanjutnya
            </Button>
          </div>
        </div>
      )}

      {/* DELETE CONFIRMATION DIALOG */}
      <Dialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <DialogContent className="dark:bg-gray-900 dark:border-gray-700">
          <DialogHeader>
            <DialogTitle className="dark:text-gray-100">
              Hapus Transaksi Batal?
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Apakah Anda yakin ingin menghapus record transaksi batal ini?
            </p>
            {selectedBatal && (
              <div className="bg-[#ece4cf] dark:bg-gray-800 p-3 rounded text-sm space-y-1">
                <p>
                  <span className="font-semibold dark:text-gray-200">Blok:</span> {selectedBatal.blok_no}
                </p>
                <p>
                  <span className="font-semibold dark:text-gray-200">Nominal:</span>{" "}
                  {formatCurrency(selectedBatal.jumlah)}
                </p>
                <p>
                  <span className="font-semibold dark:text-gray-200">Alasan:</span> {selectedBatal.alasan_batal}
                </p>
              </div>
            )}
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDeleteConfirm(false)}
              className="dark:border-gray-700"
            >
              Batal
            </Button>
            <Button
              variant="destructive"
              onClick={confirmDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
