import React, { createContext, useContext, useState, useEffect, useCallback } from "react";
import { useAuth } from "./AuthContext";
import { API_BASE_URL } from "../config/api";

const TenantContext = createContext(null);

export const TenantProvider = ({ children }) => {
  const { user, token } = useAuth();
  const [currentTenant, setCurrentTenant] = useState(null);
  const [tenantList, setTenantList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  const isVendorAdmin = user?.role === "admin" && 
    user?.permissions && 
    (typeof user.permissions === "string" 
      ? JSON.parse(user.permissions) 
      : user.permissions)?.["vendor-dashboard"]?.read === true;

  // Load tenant dari localStorage (persist pilihan user)
  useEffect(() => {
    const saved = localStorage.getItem("currentTenant");
    if (saved) {
      try { setCurrentTenant(JSON.parse(saved)); } catch (_) {}
    }
  }, []);

  // Fetch daftar tenant (untuk vendor admin)
  const fetchTenants = useCallback(async () => {
    if (!token || !isVendorAdmin) return;
    setIsLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setTenantList(data);
        // Auto-select pertama kalau belum ada pilihan
        if (!currentTenant && data.length > 0) {
          switchTenant(data[0]);
        }
      }
    } catch (_) {}
    setIsLoading(false);
  }, [token, isVendorAdmin]);

  useEffect(() => { fetchTenants(); }, [fetchTenants]);

  const switchTenant = useCallback((tenant) => {
    setCurrentTenant(tenant);
    localStorage.setItem("currentTenant", JSON.stringify(tenant));
  }, []);

  const clearTenant = useCallback(() => {
    setCurrentTenant(null);
    localStorage.removeItem("currentTenant");
  }, []);

  // Header X-Tenant-ID untuk setiap API call
  const tenantHeader = currentTenant
    ? { "X-Tenant-ID": currentTenant.id }
    : {};

  return (
    <TenantContext.Provider value={{
      currentTenant,
      tenantList,
      isLoading,
      isVendorAdmin,
      switchTenant,
      clearTenant,
      fetchTenants,
      tenantHeader,
    }}>
      {children}
    </TenantContext.Provider>
  );
};

export const useTenant = () => {
  const ctx = useContext(TenantContext);
  if (!ctx) throw new Error("useTenant must be used within TenantProvider");
  return ctx;
};
