import { useState } from "react";
import DaftarKasbon from "./DaftarKasbon";
import PelunasanKasbon from "./PelunasanKasbon";
import RekapKasbon from "./RekapKasbon";

export default function KasbonPage() {
  const [activeTab, setActiveTab] = useState("daftar");

  const tabs = [
    { id: "daftar", label: "Daftar Kasbon", icon: "📋" },
    { id: "pelunasan", label: "Pelunasan Kasbon", icon: "✓" },
    { id: "rekap", label: "Rekap Kasbon", icon: "📊" },
  ];

  return (
    <div className="w-full">
      {/* Tab Navigation */}
      <div className="border-b border-[#d5cebc] dark:border-gray-700 mb-6">
        <div className="flex gap-0">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-6 py-4 font-medium transition-colors border-b-2 ${
                activeTab === tab.id
                  ? "border-blue-500 text-blue-600 dark:text-blue-400"
                  : "border-transparent text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200"
              }`}
            >
              <span className="mr-2">{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === "daftar" && <DaftarKasbon />}
        {activeTab === "pelunasan" && <PelunasanKasbon />}
        {activeTab === "rekap" && <RekapKasbon />}
      </div>
    </div>
  );
}
