import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import {
  LayoutDashboard, MapPin, CreditCard, Activity,
  Users, Shield, LogOut, Menu, X, ChevronRight, Store, Lock, UserCog, FileText, Receipt, Landmark, Layout,
} from 'lucide-react';

const MENU_ITEMS = [
  { id: 'dashboard',       label: 'Dashboard',          icon: LayoutDashboard, path: '/vendor' },
  { id: 'onboarding',      label: 'Onboarding Wilayah', icon: MapPin,          path: '/vendor/onboarding' },
  { id: 'subscription',    label: 'Subscription',       icon: CreditCard,      path: '/vendor/subscription' },
  { id: 'invoice',         label: 'Invoice',            icon: Receipt,         path: '/vendor/invoice' },
  { id: 'payment-gateway', label: 'Payment Gateway',   icon: Landmark,        path: '/vendor/payment-gateway' },
  { id: 'monitoring',      label: 'Monitoring',         icon: Activity,        path: '/vendor/monitoring' },
  { id: 'surat-template',  label: 'Template Surat',     icon: FileText,        path: '/vendor/surat-template' },
  { id: 'cms-landing',     label: 'CMS Landing Page',   icon: Layout,          path: '/vendor/cms-landing' },
  { id: 'accounts',        label: 'Akun Vendor',        icon: UserCog,         path: '/vendor/accounts' },
  { id: 'users',           label: 'Manajemen Pengguna', icon: Users,           path: '/vendor/user-permissions' },
  { id: 'roles',           label: 'Manajemen Role',     icon: Shield,          path: '/vendor/roles' },
  { id: 'permissions',     label: 'Hak Akses',          icon: Lock,            path: '/vendor/permissions' },
];

export default function VendorLayout({ children }) {
  const location  = useLocation();
  const navigate  = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Force light mode — vendor panel never uses dark theme
  useEffect(() => {
    const html = document.documentElement;
    const wasDark = html.classList.contains('dark');
    html.classList.remove('dark');
    return () => { if (wasDark) html.classList.add('dark'); };
  }, []);

  const vendorName = (() => {
    try {
      const raw = localStorage.getItem('vendor_user');
      return raw ? JSON.parse(raw).name : 'Vendor';
    } catch { return 'Vendor'; }
  })();

  const handleLogout = () => {
    localStorage.removeItem('vendor_token');
    localStorage.removeItem('vendor_user');
    navigate('/vendor-login');
  };

  const isActive = (path) =>
    path === '/vendor' ? location.pathname === '/vendor' : location.pathname.startsWith(path);

  const Sidebar = () => (
    <div className="flex flex-col h-full bg-white border-r border-gray-200">
      {/* Logo */}
      <div className="flex items-center gap-3 px-5 py-5 border-b border-gray-100">
        <div className="w-9 h-9 bg-[#ed6f5c] rounded-xl flex items-center justify-center flex-shrink-0">
          <Store size={18} className="text-white" />
        </div>
        <div className="min-w-0">
          <p className="font-bold text-gray-900 text-sm truncate">Vendor</p>
          <p className="text-xs text-gray-400 truncate">{vendorName}</p>
        </div>
      </div>

      {/* Menu */}
      <nav className="flex-1 px-3 py-4 space-y-0.5 overflow-y-auto">
        {MENU_ITEMS.map(item => {
          const Icon   = item.icon;
          const active = isActive(item.path);
          return (
            <Link key={item.id} to={item.path}
              onClick={() => setSidebarOpen(false)}
              className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all group ${
                active
                  ? 'bg-[#fdf1ef] text-[#ed6f5c]'
                  : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
              }`}>
              <Icon size={17} className={active ? 'text-[#ed6f5c]' : 'text-gray-400 group-hover:text-gray-600'} />
              <span className="flex-1">{item.label}</span>
              {active && <ChevronRight size={13} className="text-[#ed6f5c]" />}
            </Link>
          );
        })}
      </nav>

      {/* Logout */}
      <div className="p-3 border-t border-gray-100">
        <button onClick={handleLogout}
          className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium text-red-500 hover:bg-red-50 transition-colors">
          <LogOut size={17} />
          Keluar
        </button>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      {/* Desktop Sidebar */}
      <aside className="hidden lg:flex flex-col w-56 flex-shrink-0">
        <Sidebar />
      </aside>

      {/* Mobile Sidebar Overlay */}
      {sidebarOpen && (
        <div className="lg:hidden fixed inset-0 z-40 flex">
          <div className="fixed inset-0 bg-black/50" onClick={() => setSidebarOpen(false)} />
          <aside className="relative z-50 w-56 flex flex-col">
            <Sidebar />
          </aside>
        </div>
      )}

      {/* Main */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Topbar */}
        <header className="bg-white border-b border-gray-200 px-5 py-3 flex items-center justify-between flex-shrink-0">
          <button className="lg:hidden text-gray-500" onClick={() => setSidebarOpen(true)}>
            <Menu size={20} />
          </button>
          <div className="flex-1" />
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-[#ed6f5c] flex items-center justify-center">
              <span className="text-white font-bold text-sm">
                {vendorName.charAt(0).toUpperCase()}
              </span>
            </div>
            <div className="hidden sm:block text-right">
              <p className="text-sm font-semibold text-gray-800 leading-tight">{vendorName}</p>
              <p className="text-xs text-gray-400">Vendor</p>
            </div>
          </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-5 bg-gray-50">
          {children}
        </main>
      </div>
    </div>
  );
}

