import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { API_BASE_URL } from '../../config/api';
import { MapPin, Home, Users, CheckCircle, AlertCircle, RefreshCw } from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';

const DataRT = () => {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => { fetchData(); }, [token, rtId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = rtId ? { rt_id: rtId } : {};
      const res = await axios.get(`${API_BASE_URL}/api/rw/rt`, { headers, params });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data RT...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const rtList = data?.data || [];

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Data RT</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
            <MapPin className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data RT</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Daftar RT dalam RW — {data?.total_rt || 0} blok
            </p>
          </div>
        </div>
        <button
          onClick={fetchData}
          className="flex items-center gap-2 px-4 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors"
        >
          <RefreshCw className="h-4 w-4" />
          Refresh
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center">
            <MapPin className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">Total RT/Blok</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">{data?.total_rt || 0}</p>
          </div>
        </div>
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-green-500 to-emerald-600 rounded-xl flex items-center justify-center">
            <Home className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">Total Rumah</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">
              {rtList.reduce((s, r) => s + (r.total_rumah || 0), 0)}
            </p>
          </div>
        </div>
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-violet-600 rounded-xl flex items-center justify-center">
            <Users className="h-6 w-6 text-white" />
          </div>
          <div>
            <p className="text-sm text-gray-500 dark:text-gray-400">Total Warga</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">
              {rtList.reduce((s, r) => s + (r.jumlah_warga || 0), 0)}
            </p>
          </div>
        </div>
      </div>

      {/* RT Table */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Daftar RT / Blok
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            RT terdaftar di bawah RW ini
          </p>
        </div>
        {rtList.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Nama RT</TableHead>
                <TableHead>Blok</TableHead>
                <TableHead>Alamat</TableHead>
                <TableHead className="text-center">Total Rumah</TableHead>
                <TableHead className="text-center">Rumah Aktif</TableHead>
                <TableHead className="text-center">Rumah Kosong</TableHead>
                <TableHead className="text-center">Jumlah Warga</TableHead>
                <TableHead className="text-center">Status</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rtList.map((rt, idx) => (
                <TableRow key={idx}>
                  <TableCell className="font-semibold text-gray-900 dark:text-white">
                    {rt.nama_rt}
                  </TableCell>
                  <TableCell>
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-bold bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border border-blue-200">
                      {rt.blok || '-'}
                    </span>
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400 max-w-[180px]">
                    <span className="truncate block">{rt.alamat || '-'}</span>
                  </TableCell>
                  <TableCell className="text-center">{rt.total_rumah}</TableCell>
                  <TableCell className="text-center">
                    <span className="text-green-600 font-medium">{rt.rumah_aktif}</span>
                  </TableCell>
                  <TableCell className="text-center">
                    <span className={rt.rumah_kosong > 0 ? 'text-amber-600 font-medium' : 'text-gray-400'}>
                      {rt.rumah_kosong}
                    </span>
                  </TableCell>
                  <TableCell className="text-center">
                    <span className="font-medium text-gray-900 dark:text-white">
                      {rt.jumlah_warga || 0}
                    </span>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge
                      variant="outline"
                      className={rt.status === 'aktif'
                        ? 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20'
                        : 'border-gray-400 text-gray-500'
                      }
                    >
                      {rt.status === 'aktif' ? (
                        <><CheckCircle className="h-3 w-3 mr-1" />Aktif</>
                      ) : (
                        <><AlertCircle className="h-3 w-3 mr-1" />Tidak Aktif</>
                      )}
                    </Badge>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <MapPin className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Belum ada data RT</p>
            <p className="text-sm text-gray-400 dark:text-gray-500 mt-1">
              Data RT diambil otomatis dari data rumah yang sudah ada
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DataRT;
