import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useKelurahanFilter } from '../../contexts/KelurahanFilterContext';
import { API_BASE_URL } from '../../config/api';
import { AlertCircle, RefreshCw, Eye, Filter } from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle
} from '@/components/ui/dialog';

const STATUS_COLORS = {
  open: 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20',
  in_progress: 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  resolved: 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
  closed: 'border-gray-400 text-gray-500 bg-[#ece4cf] dark:bg-gray-700',
};

const PRIORITAS_COLORS = {
  rendah: 'border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  sedang: 'border-amber-400 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  tinggi: 'border-red-400 text-red-600 bg-red-50 dark:bg-red-900/20',
  kritis: 'border-red-700 text-red-800 bg-red-100 dark:bg-red-900/40',
};

const PengaduanKelurahan = () => {
  const { token } = useAuth();
  const { rwId } = useKelurahanFilter();
  const [data, setData] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterStatus, setFilterStatus] = useState('');
  const [filterKategori, setFilterKategori] = useState('');
  const [viewItem, setViewItem] = useState(null);

  useEffect(() => { fetchData(); }, [token, rwId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (filterStatus) params.append('status', filterStatus);
      if (filterKategori) params.append('kategori', filterKategori);
      if (rwId) params.append('rw_id', rwId);
      const [listRes, statsRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/kelurahan/complaints?${params}`, { headers }),
        axios.get(`${API_BASE_URL}/api/pengaduan/stats/summary`, { headers }),
      ]);
      setData(Array.isArray(listRes.data) ? listRes.data : []);
      setStats(statsRes.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
    : '-';

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data pengaduan...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  // Group by kategori for summary
  const byKategori = data.reduce((acc, p) => {
    acc[p.kategori] = (acc[p.kategori] || 0) + 1;
    return acc;
  }, {});

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengaduan</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-red-500 to-rose-600 rounded-xl flex items-center justify-center shadow">
            <AlertCircle className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Pengaduan Wilayah</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Monitoring pengaduan seluruh wilayah</p>
          </div>
        </div>
        <button onClick={fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
          <RefreshCw className="h-4 w-4" />
        </button>
      </div>

      {/* Stats */}
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[
            { label: 'Total', value: stats.total, color: 'from-gray-500 to-gray-600' },
            { label: 'Open', value: stats.open, color: 'from-red-500 to-rose-600' },
            { label: 'Dalam Proses', value: stats.in_progress, color: 'from-amber-500 to-orange-600' },
            { label: 'Selesai', value: stats.resolved, color: 'from-green-500 to-emerald-600' },
          ].map((s, i) => (
            <div key={i} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-3">
              <div className={`w-10 h-10 bg-gradient-to-br ${s.color} rounded-lg flex items-center justify-center`}>
                <AlertCircle className="h-5 w-5 text-white" />
              </div>
              <div>
                <p className="text-xs text-gray-500 dark:text-gray-400">{s.label}</p>
                <p className="text-xl font-bold text-gray-900 dark:text-white">{s.value}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Kategori Distribution */}
      {Object.keys(byKategori).length > 0 && (
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4">
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">Distribusi per Kategori</h3>
          <div className="flex flex-wrap gap-2">
            {Object.entries(byKategori).map(([kat, count]) => (
              <div key={kat} className="flex items-center gap-2 px-3 py-1.5 bg-[#ece4cf] dark:bg-gray-700 rounded-full">
                <span className="text-sm font-medium text-gray-700 dark:text-gray-300 capitalize">{kat}</span>
                <Badge variant="outline" className="text-xs">{count}</Badge>
              </div>
            ))}
          </div>
        </div>
      )}

{/* Filters */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex flex-wrap gap-3 items-end">
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Status</label>
          <Select value={filterStatus || "all"} onValueChange={v => { setFilterStatus(v === "all" ? "" : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Status" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Status</SelectItem>
              <SelectItem value="open">Open</SelectItem>
              <SelectItem value="in_progress">Dalam Proses</SelectItem>
              <SelectItem value="resolved">Selesai</SelectItem>
              <SelectItem value="closed">Ditutup</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Kategori</label>
          <Select value={filterKategori || "all"} onValueChange={v => { setFilterKategori(v === "all" ? "" : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Kategori" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Kategori</SelectItem>
              <SelectItem value="infrastruktur">Infrastruktur</SelectItem>
              <SelectItem value="keamanan">Keamanan</SelectItem>
              <SelectItem value="kebersihan">Kebersihan</SelectItem>
              <SelectItem value="sosial">Sosial</SelectItem>
              <SelectItem value="umum">Umum</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <button onClick={() => { setFilterStatus(''); setFilterKategori(''); setTimeout(fetchData, 100); }}
          className="px-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 flex items-center gap-1">
          <Filter className="h-3.5 w-3.5" />Reset
        </button>
      </div>

      {/* Table */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Daftar Pengaduan ({data.length})
          </h3>
        </div>
        {data.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Judul</TableHead>
                <TableHead>Kategori</TableHead>
                <TableHead>Pelapor</TableHead>
                <TableHead>Blok</TableHead>
                <TableHead>Prioritas</TableHead>
                <TableHead>Eskalasi</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Tanggal</TableHead>
                <TableHead className="text-center">Detail</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.map((p) => (
                <TableRow key={p.id}>
                  <TableCell className="font-medium text-gray-900 dark:text-white max-w-[180px]">
                    <span className="truncate block">{p.judul}</span>
                  </TableCell>
                  <TableCell className="text-sm capitalize">{p.kategori}</TableCell>
                  <TableCell className="text-sm text-gray-600 dark:text-gray-400">{p.nama_pelapor || '-'}</TableCell>
                  <TableCell className="text-sm">{p.blok_rumah || '-'}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className={PRIORITAS_COLORS[p.prioritas] || ''}>{p.prioritas}</Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={
                      p.eskalasi === 'Kelurahan' ? 'border-purple-500 text-purple-600 bg-purple-50 dark:bg-purple-900/20' :
                      p.eskalasi === 'RW' ? 'border-blue-500 text-blue-600 bg-blue-50 dark:bg-blue-900/20' :
                      'border-gray-400 text-gray-500'
                    }>
                      {p.eskalasi || 'RT'}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={STATUS_COLORS[p.status] || ''}>
                      {p.status === 'open' ? 'Open' : p.status === 'in_progress' ? 'Proses' : p.status === 'resolved' ? 'Selesai' : 'Ditutup'}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(p.created_at)}</TableCell>
                  <TableCell className="text-center">
                    <button onClick={() => setViewItem(p)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                      <Eye className="h-3.5 w-3.5" />
                    </button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <AlertCircle className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Belum ada pengaduan</p>
          </div>
        )}
      </div>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-red-500" />
              {viewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>{viewItem.status}</Badge>
                <Badge variant="outline" className={PRIORITAS_COLORS[viewItem.prioritas] || ''}>{viewItem.prioritas}</Badge>
                <Badge variant="outline">{viewItem.kategori}</Badge>
                {viewItem.eskalasi && <Badge variant="outline">Eskalasi: {viewItem.eskalasi}</Badge>}
              </div>
              <div className="grid grid-cols-2 gap-2 text-gray-600 dark:text-gray-400">
                <div><span className="font-medium">Pelapor:</span> {viewItem.nama_pelapor || '-'}</div>
                <div><span className="font-medium">Blok:</span> {viewItem.blok_rumah || '-'}</div>
                <div><span className="font-medium">Tanggal:</span> {formatDate(viewItem.created_at)}</div>
                {viewItem.ditangani_oleh && <div><span className="font-medium">Ditangani:</span> {viewItem.ditangani_oleh}</div>}
              </div>
              <div>
                <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Deskripsi:</p>
                <p className="text-gray-600 dark:text-gray-400 bg-[#ece4cf] dark:bg-gray-800 rounded p-3">{viewItem.deskripsi}</p>
              </div>
              {viewItem.catatan_penanganan && (
                <div>
                  <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Catatan Penanganan:</p>
                  <p className="text-gray-600 dark:text-gray-400 bg-green-50 dark:bg-green-900/20 rounded p-3">{viewItem.catatan_penanganan}</p>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PengaduanKelurahan;
