import React, { useState, useEffect, useCallback } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../components/ui/table";
import { Input } from "../components/ui/input";
import { Button } from "../components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "../components/ui/dialog";
import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction
} from "../components/ui/alert-dialog";
import { Loader2, Trash2, Eye, Download } from "lucide-react";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "../components/ui/tooltip";
import { API_BASE_URL } from "../config/api";
import { useAuth } from "../contexts/AuthContext";
import { toast } from "sonner";

export default function AktivitasLog() {
  const { token } = useAuth();
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState(null);

  // Pagination & Filter
  const [page, setPage] = useState(0);
  const [limit, setLimit] = useState(20);
  const [search, setSearch] = useState("");
  const [selectedMenu, setSelectedMenu] = useState("");
  const [selectedAction, setSelectedAction] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  // Modal
  const [selectedLog, setSelectedLog] = useState(null);
  const [showDetail, setShowDetail] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  // Fetch logs
  const fetchLogs = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        skip: page * limit,
        limit: limit,
        search: search,
        menu: selectedMenu === "__all__" ? "" : selectedMenu,
        action: selectedAction === "__all__" ? "" : selectedAction,
        start_date: startDate,
        end_date: endDate,
      });

      const response = await fetch(
        `${API_BASE_URL}/api/aktivitas-log/?${params}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (!response.ok) throw new Error("Failed to fetch logs");
      const data = await response.json();
      setLogs(data);
    } catch (error) {
      console.error("Error fetching logs:", error);
      toast.error("Gagal mengambil data log");
    } finally {
      setLoading(false);
    }
  }, [page, limit, search, selectedMenu, selectedAction, startDate, endDate, token]);

  // Fetch stats
  const fetchStats = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/aktivitas-log/stats`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data);
      }
    } catch (error) {
      console.error("Error fetching stats:", error);
    }
  }, [token]);

  useEffect(() => {
    fetchLogs();
    fetchStats();
  }, [fetchLogs, fetchStats]);

  // Delete log
  const handleDelete = async (logId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/aktivitas-log/${logId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) throw new Error("Failed to delete log");
      toast.success("Log berhasil dihapus");
      setDeleteConfirm(null);
      fetchLogs();
    } catch (error) {
      console.error("Error deleting log:", error);
      toast.error("Gagal menghapus log");
    }
  };

  // Export to CSV
  const handleExport = () => {
    if (logs.length === 0) {
      toast.error("Tidak ada data untuk di-export");
      return;
    }

    const headers = ["Tanggal", "User", "Menu", "Action", "Deskripsi"];
    const rows = logs.map((log) => [
      log.created_at_formatted,
      log.fullname,
      log.menu,
      log.action,
      log.deskripsi,
    ]);

    const csv = [
      headers.join(","),
      ...rows.map((row) => row.map((cell) => `"${cell}"`).join(",")),
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv" });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `aktivitas-log-${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);

    toast.success("Data berhasil di-export");
  };

  // Get unique menus and actions from stats (includes ALL logs, not just current page)
  const menus = stats && stats.menu_stats ? Object.keys(stats.menu_stats).filter(Boolean) : [];
  const actions = stats && stats.action_stats ? Object.keys(stats.action_stats).filter(Boolean) : [];

  return (
    <div className="min-h-screen bg-[#efe7d2] dark:bg-gradient-to-br dark:from-gray-900 dark:to-gray-800 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
            Log Aktivitas
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            Pantau semua aktivitas user dalam sistem
          </p>
        </div>

        {/* Stats Cards */}
        {stats && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-6">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-2">
                Total Log
              </p>
              <p className="text-3xl font-bold text-blue-600 dark:text-blue-400">
                {stats.total_logs}
              </p>
            </div>
            <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-6">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-2">
                Total Menu
              </p>
              <p className="text-3xl font-bold text-green-600 dark:text-green-400">
                {Object.keys(stats.menu_stats || {}).length}
              </p>
            </div>
            <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-6">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-2">
                Tipe Aksi
              </p>
              <p className="text-3xl font-bold text-purple-600 dark:text-purple-400">
                {Object.keys(stats.action_stats || {}).length}
              </p>
            </div>
          </div>
        )}

        {/* Filters */}
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-6 mb-8">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-4">
            {/* Search */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Cari
              </label>
              <Input
                placeholder="Cari deskripsi, user..."
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  setPage(0);
                }}
                className="bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600"
              />
            </div>

            {/* Menu Filter */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Menu
              </label>
              <Select value={selectedMenu} onValueChange={(value) => {
                setSelectedMenu(value);
                setPage(0);
              }}>
                <SelectTrigger className="bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600">
                  <SelectValue placeholder="Semua menu" />
                </SelectTrigger>
                <SelectContent className="bg-[#f7f1de] border-[#d5cebc] dark:bg-gray-700">
                  <SelectItem value="__all__">Semua menu</SelectItem>
                  {menus.map((menu) => (
                    <SelectItem key={menu} value={menu}>
                      {menu}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Action Filter */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Action
              </label>
              <Select value={selectedAction} onValueChange={(value) => {
                setSelectedAction(value);
                setPage(0);
              }}>
                <SelectTrigger className="bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600">
                  <SelectValue placeholder="Semua action" />
                </SelectTrigger>
                <SelectContent className="bg-[#f7f1de] border-[#d5cebc] dark:bg-gray-700">
                  <SelectItem value="__all__">Semua action</SelectItem>
                  {actions.map((action) => (
                    <SelectItem key={action} value={action}>
                      {action}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Date Range */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Dari
              </label>
              <Input
                type="date"
                value={startDate}
                onChange={(e) => {
                  setStartDate(e.target.value);
                  setPage(0);
                }}
                className="bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Hingga
              </label>
              <Input
                type="date"
                value={endDate}
                onChange={(e) => {
                  setEndDate(e.target.value);
                  setPage(0);
                }}
                className="bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600"
              />
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 flex-wrap">
            <Button
              onClick={() => {
                setSearch("");
                setSelectedMenu("");
                setSelectedAction("");
                setStartDate("");
                setEndDate("");
                setPage(0);
              }}
              variant="outline"
              className="dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700"
            >
              Reset Filter
            </Button>
            <Button
              onClick={handleExport}
              variant="outline"
              className="dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700 flex items-center gap-2"
            >
              <Download size={16} />
              Export CSV
            </Button>
          </div>
        </div>

        {/* Table */}
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          {loading ? (
            <div className="flex items-center justify-center h-64">
              <Loader2 className="animate-spin text-gray-400" size={40} />
            </div>
          ) : logs.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-500 dark:text-gray-400">
                Tidak ada data log aktivitas
              </p>
            </div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="border-b dark:border-gray-700">
                      <TableHead className="dark:text-gray-300">
                        Tanggal
                      </TableHead>
                      <TableHead className="dark:text-gray-300">
                        User
                      </TableHead>
                      <TableHead className="dark:text-gray-300">
                        Menu
                      </TableHead>
                      <TableHead className="dark:text-gray-300">
                        Action
                      </TableHead>
                      <TableHead className="dark:text-gray-300">
                        Deskripsi
                      </TableHead>
                      <TableHead className="dark:text-gray-300 text-right">
                        Aksi
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {logs.map((log) => (
                      <TableRow
                        key={log.id}
                        className="border-b dark:border-gray-700 hover:bg-[#e4dcc8] dark:hover:bg-gray-700/50 transition-colors"
                      >
                        <TableCell className="dark:text-gray-300 text-sm">
                          {log.created_at_formatted}
                        </TableCell>
                        <TableCell className="dark:text-gray-300">
                          <div className="font-medium">{log.fullname}</div>
                          <div className="text-sm text-gray-500 dark:text-gray-400">
                            @{log.username}
                          </div>
                        </TableCell>
                        <TableCell className="dark:text-gray-300">
                          <span className="px-3 py-1 bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-200 rounded-full text-sm font-medium">
                            {log.menu}
                          </span>
                        </TableCell>
                        <TableCell className="dark:text-gray-300">
                          <span
                            className={`px-3 py-1 rounded-full text-sm font-medium ${
                              log.action === "CREATE"
                                ? "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-200"
                                : log.action === "UPDATE"
                                ? "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200"
                                : log.action === "DELETE"
                                ? "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200"
                                : "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200"
                            }`}
                          >
                            {log.action}
                          </span>
                        </TableCell>
                        <TableCell className="dark:text-gray-300 max-w-xs">
                          <TooltipProvider>
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <div className="truncate cursor-help">{log.deskripsi}</div>
                              </TooltipTrigger>
                              <TooltipContent className="max-w-sm bg-gray-900 dark:bg-gray-700 text-white dark:text-gray-100 rounded p-2 text-sm">
                                <p className="whitespace-normal">{log.deskripsi}</p>
                              </TooltipContent>
                            </Tooltip>
                          </TooltipProvider>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-2">
                            <button
                              onClick={() => {
                                setSelectedLog(log);
                                setShowDetail(true);
                              }}
                              className="p-2 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                              title="Lihat detail"
                            >
                              <Eye size={18} />
                            </button>
                            {/* <button
                              onClick={() => setDeleteConfirm(log.id)}
                              className="p-2 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                              title="Hapus log"
                            >
                              <Trash2 size={18} />
                            </button> */}
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* Pagination */}
              <div className="border-t dark:border-gray-700 p-6 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Tampilkan per halaman:
                  </span>
                  <Select value={limit.toString()} onValueChange={(value) => {
                    setLimit(parseInt(value));
                    setPage(0);
                  }}>
                    <SelectTrigger className="w-20 bg-[#ece4cf] border-[#d5cebc] dark:bg-gray-700 dark:text-white dark:border-gray-600">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="bg-[#f7f1de] border-[#d5cebc] dark:bg-gray-700">
                      <SelectItem value="10">10</SelectItem>
                      <SelectItem value="20">20</SelectItem>
                      <SelectItem value="50">50</SelectItem>
                      <SelectItem value="100">100</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex items-center gap-2">
                  <Button
                    onClick={() => setPage(Math.max(0, page - 1))}
                    disabled={page === 0}
                    variant="outline"
                    className="dark:border-gray-600 dark:text-gray-300"
                  >
                    Sebelumnya
                  </Button>
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Halaman {page + 1}
                  </span>
                  <Button
                    onClick={() => setPage(page + 1)}
                    disabled={logs.length < limit}
                    variant="outline"
                    className="dark:border-gray-600 dark:text-gray-300"
                  >
                    Selanjutnya
                  </Button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Log Aktivitas?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deleteConfirm && handleDelete(deleteConfirm)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Detail Modal */}
      {selectedLog && (
        <Dialog open={showDetail} onOpenChange={setShowDetail}>
          <DialogContent className="bg-[#f7f1de] border-[#d5cebc] dark:bg-gray-800 dark:border-gray-700">
            <DialogHeader>
              <DialogTitle className="dark:text-white">
                Detail Aktivitas Log
              </DialogTitle>
              <DialogDescription className="dark:text-gray-400">
                Informasi lengkap tentang aktivitas yang dipilih
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-6 max-h-[70vh] overflow-y-auto">
              {/* Timestamp Section */}
              <div className="border-l-4 border-blue-500 dark:border-blue-400 pl-4">
                <p className="text-xs uppercase tracking-wide font-semibold text-gray-500 dark:text-gray-400 mb-2">
                  Waktu Aktivitas
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {selectedLog.created_at_formatted}
                </p>
              </div>

              {/* User Information Section */}
              <div className="border-l-4 border-purple-500 dark:border-purple-400 pl-4">
                <p className="text-xs uppercase tracking-wide font-semibold text-gray-500 dark:text-gray-400 mb-3">
                  Informasi Pengguna
                </p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="bg-[#ece4cf] dark:bg-gray-700/50 rounded p-3">
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                      Nama
                    </p>
                    <p className="text-sm font-semibold text-gray-900 dark:text-white">
                      {selectedLog.fullname}
                    </p>
                  </div>
                  <div className="bg-[#ece4cf] dark:bg-gray-700/50 rounded p-3">
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                      Username
                    </p>
                    <p className="text-sm font-mono text-gray-700 dark:text-gray-300">
                      @{selectedLog.username}
                    </p>
                  </div>
                </div>
              </div>

              {/* Action Information Section */}
              <div className="border-l-4 border-green-500 dark:border-green-400 pl-4">
                <p className="text-xs uppercase tracking-wide font-semibold text-gray-500 dark:text-gray-400 mb-3">
                  Detail Aksi
                </p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="bg-[#ece4cf] dark:bg-gray-700/50 rounded p-3">
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                      Menu
                    </p>
                    <p className="inline-block text-xs font-semibold px-2 py-1 bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-200 rounded">
                      {selectedLog.menu}
                    </p>
                  </div>
                  <div className="bg-[#ece4cf] dark:bg-gray-700/50 rounded p-3">
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                      Action
                    </p>
                    <p className={`inline-block text-xs font-semibold px-2 py-1 rounded ${
                      selectedLog.action === "CREATE"
                        ? "bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-200"
                        : selectedLog.action === "UPDATE"
                        ? "bg-yellow-100 dark:bg-yellow-900/40 text-yellow-800 dark:text-yellow-200"
                        : selectedLog.action === "DELETE"
                        ? "bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-200"
                        : "bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-300"
                    }`}>
                      {selectedLog.action}
                    </p>
                  </div>
                </div>
              </div>

              {/* Description Section */}
              <div className="border-l-4 border-orange-500 dark:border-orange-400 pl-4">
                <p className="text-xs uppercase tracking-wide font-semibold text-gray-500 dark:text-gray-400 mb-2">
                  Deskripsi
                </p>
                <div className="bg-[#ece4cf] dark:bg-gray-700/50 rounded p-3">
                  <p className="text-sm text-gray-900 dark:text-gray-100 leading-relaxed">
                    {selectedLog.deskripsi}
                  </p>
                </div>
              </div>

              {/* JSON Details Section */}
              {selectedLog.details && Object.keys(selectedLog.details).length > 0 && (
                <div className="border-l-4 border-cyan-500 dark:border-cyan-400 pl-4">
                  <p className="text-xs uppercase tracking-wide font-semibold text-gray-500 dark:text-gray-400 mb-2">
                    Detail Tambahan (JSON)
                  </p>
                  <pre className="bg-gray-900 dark:bg-gray-950 p-4 rounded text-xs overflow-x-auto overflow-y-auto max-h-64 text-green-400 font-mono border border-gray-700 dark:border-gray-600" style={{lineHeight: '1.6'}}>
                    <code>{JSON.stringify(selectedLog.details, null, 2)}</code>
                  </pre>
                </div>
              )}
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}
