import React, { useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { useAuth } from '@/contexts/AuthContext';
import { useRolePermissions } from '@/hooks/useRolePermissions';
import { Edit, X, Check } from 'lucide-react';
import { Checkbox } from '@/components/ui/checkbox';

export default function RumahTable({
  data,
  onEdit,
  onDelete,
  selectedRows = [],
  setSelectedRows = () => {},
}) {
  const { token, user } = useAuth();
  const { canRead, canEdit } = useRolePermissions(user?.role, token);

  const toggleRow = (id) => {
    setSelectedRows(
      selectedRows.includes(id)
        ? selectedRows.filter((r) => r !== id)
        : [...selectedRows, id]
    );
  };

  const toggleAll = () => {
    if (selectedRows.length === data.length) setSelectedRows([]);
    else setSelectedRows(data.map((r) => r.id));
  };

  const handleDelete = async (rumahId) => {
    if (window.confirm('Yakin ingin menghapus data rumah ini?')) {
      try {
        const response = await fetch(`${API_BASE_URL}/api/rumah/${rumahId}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        });

        if (!response.ok) {
          throw new Error('Gagal menghapus data');
        }

        toast.success('Data rumah berhasil dihapus');
        onDelete();
      } catch (error) {
        console.error('Error:', error);
        toast.error(error.message || 'Gagal menghapus data');
      }
    }
  };

  const getStatusPenguniColor = (status) => {
    const colors = {
      'Pemilik': 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200',
      'Penghuni Kontrak': 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200',
      'Keluarga Pemilik': 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
      'Pemilik Tidak Tinggal': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
      'Rumah Usaha': 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200',
      'Kosong': 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200',
    };
    return colors[status] || 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200';
  };

  const getJenisPemilikColor = (jenis) => {
    const colors = {
      'Milik Sendiri': 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200',
      'Sewa / Kontrak': 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200',
      'Lainnya': 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-200',
    };
    return colors[jenis] || 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-200';
  };

  return (
    <Table className="border rounded-lg bg-[#f7f1de] dark:bg-gray-900 shadow-sm">
      <TableHeader>
        <TableRow className="dark:border-gray-700">
          {/* CHECKBOX */}
          <TableHead className="w-10 text-gray-700 dark:text-gray-300">
            <Checkbox
              checked={selectedRows.length === data.length && data.length > 0}
              onCheckedChange={toggleAll}
            />
          </TableHead>

          <TableHead className="text-gray-700 dark:text-gray-300">Blok / No Rumah</TableHead>
          <TableHead className="text-gray-700 dark:text-gray-300">Nama Jalan</TableHead>
          <TableHead className="text-gray-700 dark:text-gray-300">Pemilik Sah</TableHead>
          <TableHead className="text-gray-700 dark:text-gray-300">Jenis Pemilik</TableHead>
          <TableHead className="text-gray-700 dark:text-gray-300">Status Penghuni</TableHead>
          <TableHead className="text-center text-gray-700 dark:text-gray-300">Kosong?</TableHead>
          <TableHead className="text-center text-gray-700 dark:text-gray-300">Aktif?</TableHead>
          {canRead('rumah') && canEdit('rumah') && (
            <TableHead className="text-center text-gray-700 dark:text-gray-300">Aksi</TableHead>
          )}
        </TableRow>
      </TableHeader>
      <TableBody>
        {data.length === 0 ? (
          <TableRow>
            <TableCell colSpan="11" className="text-center py-8 text-gray-500 dark:text-gray-400">
              Tidak ada data rumah
            </TableCell>
          </TableRow>
        ) : (
          data.map((rumah) => (
            <React.Fragment key={rumah.id}>
              <TableRow className="hover:bg-[#e4dcc8] dark:hover:bg-gray-800 border-b border-[#d5cebc] dark:border-gray-700">
                {/* CHECKBOX */}
                <TableCell>
                  <Checkbox
                    checked={selectedRows.includes(rumah.id)}
                    onCheckedChange={() => toggleRow(rumah.id)}
                  />
                </TableCell>

                <TableCell className="font-medium text-gray-900 dark:text-white">{rumah.blok_no}</TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400">{rumah.nama_jalan || '-'}</TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400">{rumah.pemilik_sah || '-'}</TableCell>
                <TableCell>
                  <span className={`inline-block px-2 py-1 rounded-full text-xs font-semibold ${getJenisPemilikColor(rumah.jenis_pemilik)}`}>
                    {rumah.jenis_pemilik}
                  </span>
                </TableCell>
                <TableCell>
                  <span className={`inline-block px-2 py-1 rounded-full text-xs font-semibold ${getStatusPenguniColor(rumah.status_penghuni)}`}>
                    {rumah.status_penghuni}
                  </span>
                </TableCell>
                <TableCell className="text-center">
                  {rumah.sedang_kosong ? (
                    <Check className="w-5 h-5 text-red-500 mx-auto" />
                  ) : (
                    <X className="w-5 h-5 text-green-500 mx-auto" />
                  )}
                </TableCell>
                <TableCell className="text-center">
                  {rumah.aktif ? (
                    <Check className="w-5 h-5 text-green-500 mx-auto" />
                  ) : (
                    <X className="w-5 h-5 text-red-500 mx-auto" />
                  )}
                </TableCell>
                {canRead('rumah') && canEdit('rumah') && (
                  <TableCell className="text-center">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => onEdit(rumah)}
                        className="p-1.5 rounded hover:bg-blue-100 dark:hover:bg-blue-900 text-blue-600"
                        title="Edit"
                      >
                        <Edit className="w-4 h-4" />
                      </button>
                      {/* <button
                        onClick={() => handleDelete(rumah.id)}
                        className="p-1.5 rounded hover:bg-red-100 dark:hover:bg-red-900 text-red-600"
                        title="Hapus"
                      >
                        <X className="w-4 h-4" />
                      </button> */}
                    </div>
                  </TableCell>
                )}
              </TableRow>
            </React.Fragment>
          ))
        )}
      </TableBody>
    </Table>
  );
}
