import React, { useState, useEffect, useCallback } from 'react';
import { API_BASE_URL } from '../../config/api';
import {
  Activity, Users, Building2, CreditCard, RefreshCw,
  CheckCircle, XCircle, TrendingUp, Globe, Home, Server
} from 'lucide-react';

const fmtN = (n) => new Intl.NumberFormat('id-ID').format(n || 0);
const fmt  = (n) => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);

const StatCard = ({ label, value, sub, icon: Icon, iconBg, iconColor }) => (
  <div className="bg-white  rounded-2xl border border-gray-100  p-5">
    <div className="flex items-start justify-between">
      <div>
        <p className="text-sm text-gray-500 ">{label}</p>
        <p className="text-3xl font-bold text-gray-800  mt-1">{value}</p>
        {sub && <p className="text-xs text-gray-400 mt-1">{sub}</p>}
      </div>
      <div className={`w-11 h-11 rounded-2xl flex items-center justify-center ${iconBg}`}>
        <Icon size={20} className={iconColor} />
      </div>
    </div>
  </div>
);

const Bar = ({ label, value, max, color }) => (
  <div>
    <div className="flex justify-between text-xs text-gray-500 mb-1">
      <span>{label}</span><span className="font-medium">{fmtN(value)}</span>
    </div>
    <div className="h-2 bg-gray-100  rounded-full overflow-hidden">
      <div className={`h-full rounded-full ${color}`}
        style={{ width: max ? `${Math.min(100, (value/max)*100)}%` : '0%' }} />
    </div>
  </div>
);

export default function VendorMonitoring() {
  const token  = localStorage.getItem('vendor_token');
  const [data, setData]       = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastUpdate, setLastUpdate] = useState(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/monitoring`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.ok) { setData(await res.json()); setLastUpdate(new Date()); }
    } catch (_) {}
    setLoading(false);
  }, [token]);

  useEffect(() => {
    fetchData();
    const id = setInterval(fetchData, 30000);
    return () => clearInterval(id);
  }, [fetchData]);

  const tenants = data?.tenants || {};
  const subs    = data?.subscriptions || {};
  const users   = data?.users || {};
  const types   = tenants.by_type || {};

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 ">Monitoring</h1>
          <p className="text-sm text-gray-500">
            {lastUpdate ? `Diperbarui: ${lastUpdate.toLocaleTimeString('id-ID')}` : 'Memuat...'}
          </p>
        </div>
        <button onClick={fetchData}
          className="flex items-center gap-2 px-3 py-2 border border-gray-200  rounded-xl text-sm hover:bg-gray-50">
          <RefreshCw size={14} className={loading ? 'animate-spin text-[#ed6f5c]' : ''} />
          Refresh
        </button>
      </div>

      {loading && !data ? (
        <div className="flex justify-center py-20">
          <div className="w-10 h-10 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <>
          {/* Stats */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard label="Total Tenant"  value={fmtN(tenants.total)}
              sub={`${fmtN(tenants.active)} aktif`}
              icon={Building2} iconBg="bg-[#fdf1ef]" iconColor="text-white" />
            <StatCard label="Subscription Aktif" value={fmtN(subs.active)}
              sub={`dari ${fmtN(subs.total)} total`}
              icon={CreditCard} iconBg="bg-emerald-100" iconColor="text-emerald-600" />
            <StatCard label="Total Pengguna" value={fmtN(users.total)}
              sub={`${fmtN(users.active)} aktif`}
              icon={Users} iconBg="bg-blue-100" iconColor="text-blue-600" />
            <StatCard label="Suspended"   value={fmtN(tenants.suspended || 0)}
              sub="tenant nonaktif"
              icon={XCircle} iconBg="bg-red-100" iconColor="text-red-500" />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
            {/* Hierarki Wilayah */}
            <div className="bg-white  rounded-2xl border border-gray-100  p-5">
              <h2 className="font-semibold text-gray-800  mb-4 flex items-center gap-2">
                <Globe size={16} className="text-[#ed6f5c]" /> Sebaran Wilayah
              </h2>
              <div className="space-y-3">
                <Bar label="Kelurahan" value={types.Kelurahan||0} max={Math.max(1,tenants.total)} color="bg-orange-400" />
                <Bar label="RW"        value={types.RW||0}        max={Math.max(1,tenants.total)} color="bg-[#ed6f5c]" />
                <Bar label="RT"        value={types.RT||0}        max={Math.max(1,tenants.total)} color="bg-blue-400" />
              </div>
              <div className="mt-4 pt-4 border-t border-gray-200  grid grid-cols-3 gap-2">
                {[
                  { label:'Kelurahan', val: types.Kelurahan||0, cls:'text-orange-600' },
                  { label:'RW',        val: types.RW||0,        cls:'text-[#ed6f5c]' },
                  { label:'RT',        val: types.RT||0,        cls:'text-blue-600'   },
                ].map(t => (
                  <div key={t.label} className="text-center">
                    <p className={`text-2xl font-bold ${t.cls}`}>{t.val}</p>
                    <p className="text-xs text-gray-400">{t.label}</p>
                  </div>
                ))}
              </div>
            </div>

            {/* Status System */}
            <div className="bg-white  rounded-2xl border border-gray-100  p-5">
              <h2 className="font-semibold text-gray-800  mb-4 flex items-center gap-2">
                <Server size={16} className="text-[#ed6f5c]" /> Status Sistem
              </h2>
              <div className="space-y-3">
                {[
                  { label: 'Database',         ok: true  },
                  { label: 'API Server',        ok: true  },
                  { label: 'Auth Service',      ok: !!data },
                  { label: 'Tenant Service',    ok: !!data },
                  { label: 'Subscription Svc',  ok: subs.total >= 0 },
                ].map(s => (
                  <div key={s.label} className="flex items-center justify-between py-2 border-b  last:border-0">
                    <span className="text-sm text-gray-600 ">{s.label}</span>
                    <div className={`flex items-center gap-1.5 text-xs font-medium ${s.ok ? 'text-emerald-600' : 'text-red-500'}`}>
                      {s.ok
                        ? <><CheckCircle size={13} /> Operational</>
                        : <><XCircle    size={13} /> Down</>
                      }
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Subscription Summary */}
            <div className="bg-white  rounded-2xl border border-gray-100  p-5 lg:col-span-2">
              <h2 className="font-semibold text-gray-800  mb-4 flex items-center gap-2">
                <TrendingUp size={16} className="text-[#ed6f5c]" /> Ringkasan Subscription
              </h2>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label:'Total Langganan', value: fmtN(subs.total),    cls:'text-gray-800 ' },
                  { label:'Aktif',           value: fmtN(subs.active),   cls:'text-emerald-600' },
                  { label:'Tidak Aktif',     value: fmtN(subs.inactive), cls:'text-red-500' },
                  { label:'Rate Aktif',
                    value: subs.total ? `${Math.round((subs.active/subs.total)*100)}%` : '0%',
                    cls:'text-[#ed6f5c]' },
                ].map(s => (
                  <div key={s.label} className="bg-gray-50 rounded-xl p-4 text-center">
                    <p className={`text-2xl font-bold ${s.cls}`}>{s.value}</p>
                    <p className="text-xs text-gray-400 mt-1">{s.label}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}


