import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useKelurahanFilter } from '../../contexts/KelurahanFilterContext';
import { API_BASE_URL } from '../../config/api';
import { MapPin, Building2, ChevronRight, ChevronDown, RefreshCw, Users, Home } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

const WilayahKelurahan = () => {
  const { token } = useAuth();
  const { rwId } = useKelurahanFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [expandedRW, setExpandedRW] = useState({});

  useEffect(() => { fetchData(); }, [token, rwId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (rwId) params.append('rw_id', rwId);
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/regions?${params}`, { headers });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const toggleRW = (id) => {
    setExpandedRW(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const expandAll = () => {
    const all = {};
    (data?.hierarchy || []).forEach(rw => { all[rw.id] = true; });
    setExpandedRW(all);
  };

  const collapseAll = () => setExpandedRW({});

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data wilayah...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const kelurahan = data?.kelurahan || {};
  const rwList = data?.hierarchy || [];

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Wilayah</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-xl flex items-center justify-center shadow">
            <MapPin className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Wilayah</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Hierarchy Explorer: Kelurahan → RW → RT</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button onClick={expandAll} className="px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            Expand All
          </button>
          <button onClick={collapseAll} className="px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            Collapse All
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4">
        {[
          { label: 'Total RW', value: data?.summary?.total_rw || 0, icon: Building2, color: 'from-emerald-500 to-teal-600' },
          { label: 'Total RT/Blok', value: data?.summary?.total_rt || 0, icon: MapPin, color: 'from-blue-500 to-indigo-600' },
          { label: 'Total Warga', value: data?.summary?.total_warga || 0, icon: Users, color: 'from-cyan-500 to-blue-600' },
        ].map((card, i) => (
          <div key={i} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-4">
            <div className={`w-12 h-12 bg-gradient-to-br ${card.color} rounded-xl flex items-center justify-center`}>
              <card.icon className="h-6 w-6 text-white" />
            </div>
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400">{card.label}</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{card.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Hierarchy Tree */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        {/* Kelurahan Root */}
        <div className="bg-gradient-to-r from-emerald-500 to-teal-600 p-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
              <Building2 className="h-5 w-5 text-white" />
            </div>
            <div>
              <h3 className="text-white font-bold text-lg">{kelurahan.nama_kelurahan || 'Kelurahan'}</h3>
              <p className="text-emerald-100 text-sm">
                Kec. {kelurahan.kecamatan || '-'} · {kelurahan.kota || '-'}
                {kelurahan.lurah && ` · Lurah: ${kelurahan.lurah}`}
              </p>
            </div>
          </div>
        </div>

        {/* RW List */}
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
          {rwList.length > 0 ? rwList.map((rw) => {
            const isExpanded = expandedRW[rw.id];
            const rtList = rw.rt_list || [];

            return (
              <div key={rw.id}>
                {/* RW Row */}
                <button
                  onClick={() => toggleRW(rw.id)}
                  className="w-full flex items-center gap-3 px-4 py-3 hover:bg-[#e4dcc8] dark:hover:bg-gray-700/50 transition-colors text-left"
                >
                  <div className="ml-4 flex items-center gap-2 flex-1">
                    {isExpanded
                      ? <ChevronDown className="h-4 w-4 text-gray-400" />
                      : <ChevronRight className="h-4 w-4 text-gray-400" />
                    }
                    <div className="w-8 h-8 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                      <Building2 className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                    </div>
                    <div>
                      <p className="font-medium text-gray-900 dark:text-white text-sm">
                        {rw.nama_rw}
                      </p>
                      {rw.alamat && rw.alamat !== '-' && (
                        <p className="text-xs text-gray-500 dark:text-gray-400">{rw.alamat}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-3 text-xs text-gray-500 dark:text-gray-400 mr-2">
                    <span>{rw.total_rt} RT</span>
                    <span>{rw.total_warga} warga</span>
                  </div>
                  <Badge
                    variant="outline"
                    className={rw.status === 'active'
                      ? 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20'
                      : 'border-gray-400 text-gray-500'
                    }
                  >
                    {rw.status === 'active' ? 'Aktif' : 'Tidak Aktif'}
                  </Badge>
                </button>

                {/* RT List (expanded) */}
                {isExpanded && (
                  <div className="bg-gray-50 dark:bg-gray-900/30 border-t border-gray-100 dark:border-gray-700">
                    {rtList.length > 0 ? rtList.map((rt) => (
                      <div key={rt.id} className="flex items-center gap-3 px-4 py-2.5 ml-8 border-b border-gray-100 dark:border-gray-700 last:border-0">
                        <div className="w-1 h-full border-l-2 border-gray-200 dark:border-gray-600 mr-2" />
                        <div className="w-7 h-7 bg-cyan-100 dark:bg-cyan-900/30 rounded-md flex items-center justify-center">
                          <MapPin className="h-3.5 w-3.5 text-cyan-600 dark:text-cyan-400" />
                        </div>
                        <div className="flex-1">
                          <p className="text-sm font-medium text-gray-800 dark:text-gray-200">{rt.nama_rt}</p>
                          {rt.alamat && rt.alamat !== '-' && (
                            <p className="text-xs text-gray-500 dark:text-gray-400">{rt.alamat}</p>
                          )}
                        </div>
                        <div className="flex items-center gap-4 text-xs text-gray-500 dark:text-gray-400">
                          <span className="flex items-center gap-1">
                            <Users className="h-3 w-3" />{rt.jumlah_warga} warga
                          </span>
                          <span className="flex items-center gap-1">
                            <Home className="h-3 w-3" />{rt.total_rumah} rumah
                          </span>
                        </div>
                      </div>
                    )) : (
                      <div className="px-12 py-3 text-sm text-gray-400 dark:text-gray-500 italic">
                        Belum ada data RT/Blok
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          }) : (
            <div className="text-center py-12">
              <Building2 className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">Belum ada data RW</p>
              <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                Tambahkan RW melalui menu Profil RW
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default WilayahKelurahan;
