import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import sorrySvg from '@/assets/images/sorry.svg';
import {
  Landmark, RefreshCw, Settings, CheckCircle, Clock, AlertCircle,
  XCircle, Search, ChevronDown, Eye, X, AlertTriangle, Copy,
  ExternalLink, Zap, Link2, ShieldCheck, Shield, ToggleLeft, ToggleRight,
  CreditCard, Wallet, Plus,
} from 'lucide-react';

const token  = () => localStorage.getItem('vendor_token');
const hdrs   = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });
const fmt    = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
const fmtDate = (iso) => {
  if (!iso) return '-';
  return new Date(iso).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
};
const fmtDateTime = (iso) => {
  if (!iso) return '-';
  return new Date(iso).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};

const GATEWAY_META = {
  xendit: {
    name: 'Xendit',
    desc: 'Payment gateway Indonesia — VA, QRIS, e-wallet, kartu kredit',
    apiKeyLabel: 'Secret Key',
    apiKeyPlaceholder: 'xnd_production_... atau xnd_development_...',
    extraField: 'webhook_token',
    extraLabel: 'Callback Token',
    extraPlaceholder: 'Token untuk verifikasi webhook dari Xendit',
    color: 'blue',
    bg: 'bg-blue-50',
    border: 'border-blue-100',
    text: 'text-blue-700',
    iconBg: 'bg-blue-100',
  },
  midtrans: {
    name: 'Midtrans',
    desc: 'Payment gateway Tokopedia — VA, GoPay, ShopeePay, kartu kredit',
    apiKeyLabel: 'Server Key',
    apiKeyPlaceholder: 'Mid-server-... atau SB-Mid-server-...',
    extraField: 'client_key',
    extraLabel: 'Client Key',
    extraPlaceholder: 'Mid-client-... atau SB-Mid-client-...',
    color: 'cyan',
    bg: 'bg-cyan-50',
    border: 'border-cyan-100',
    text: 'text-cyan-700',
    iconBg: 'bg-cyan-100',
  },
};

const TX_STATUS = {
  pending: { label: 'Pending',  bg: 'bg-amber-100 text-amber-700',   icon: Clock },
  paid:    { label: 'Berhasil', bg: 'bg-emerald-100 text-emerald-700', icon: CheckCircle },
  failed:  { label: 'Gagal',    bg: 'bg-red-100 text-red-700',        icon: XCircle },
  expired: { label: 'Expired',  bg: 'bg-gray-100 text-gray-500',      icon: AlertCircle },
};

function TxStatusBadge({ status }) {
  const s = TX_STATUS[status] || TX_STATUS.pending;
  const Icon = s.icon;
  return (
    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${s.bg}`}>
      <Icon size={11} /> {s.label}
    </span>
  );
}

function CopyButton({ text, label = '' }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = () => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };
  return (
    <button onClick={handleCopy}
      className="flex items-center gap-1 px-2 py-1 text-xs text-gray-500 hover:text-gray-700 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors flex-shrink-0">
      {copied ? <CheckCircle size={12} className="text-emerald-500" /> : <Copy size={12} />}
      {copied ? 'Disalin' : (label || 'Salin')}
    </button>
  );
}

// ── Gateway Config Modal ───────────────────────────────────────────────────────
function GatewayConfigModal({ open, provider, existingData, onClose, onSaved }) {
  const meta = GATEWAY_META[provider] || GATEWAY_META.xendit;
  const [form, setForm]         = useState({ api_key: '', client_key: '', webhook_token: '', is_production: false });
  const [showKey, setShowKey]   = useState(false);
  const [saving, setSaving]     = useState(false);
  const [testing, setTesting]   = useState(false);
  const [testResult, setTestResult] = useState(null);
  const [error, setError]       = useState('');
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    if (open) {
      setForm({ api_key: '', client_key: '', webhook_token: '', is_production: existingData?.is_production || false });
      setShowKey(false); setTestResult(null); setError(''); setDeleting(false);
    }
  }, [open, provider, existingData]);

  const handleTest = async () => {
    if (!form.api_key) { setTestResult({ success: false, message: 'Masukkan API key dulu' }); return; }
    setTesting(true); setTestResult(null);
    try {
      const res  = await fetch(`${API_BASE_URL}/api/vendor/payment-gateways/${provider}/test`, {
        method: 'POST', headers: hdrs(),
        body: JSON.stringify({ provider, api_key: form.api_key, is_production: form.is_production }),
      });
      const data = await res.json();
      setTestResult(data);
    } catch { setTestResult({ success: false, message: 'Gagal terhubung ke server' }); }
    setTesting(false);
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true); setError('');
    try {
      const body = {
        provider,
        is_production: form.is_production,
        ...(form.api_key       ? { api_key:       form.api_key }       : {}),
        ...(form.client_key    ? { client_key:    form.client_key }    : {}),
        ...(form.webhook_token ? { webhook_token: form.webhook_token } : {}),
      };
      const res  = await fetch(`${API_BASE_URL}/api/vendor/payment-gateways`, {
        method: 'POST', headers: hdrs(), body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      onSaved(); onClose();
    } catch (err) { setError(err.message); }
    setSaving(false);
  };

  const handleDelete = async () => {
    if (!window.confirm(`Hapus konfigurasi ${meta.name}? Semua API key akan dihapus.`)) return;
    setDeleting(true);
    try {
      await fetch(`${API_BASE_URL}/api/vendor/payment-gateways/${provider}`, {
        method: 'DELETE', headers: hdrs(),
      });
      onSaved(); onClose();
    } catch { setDeleting(false); }
  };

  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] overflow-y-auto">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between sticky top-0 bg-white">
          <div className="flex items-center gap-3">
            <div className={`w-9 h-9 ${meta.iconBg} rounded-xl flex items-center justify-center`}>
              <CreditCard size={17} className={meta.text} />
            </div>
            <div>
              <h3 className="font-bold text-gray-800">{meta.name}</h3>
              <p className="text-xs text-gray-400">Konfigurasi Gateway</p>
            </div>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>

        <form onSubmit={handleSave} className="p-5 space-y-4">
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          )}

          {/* Environment */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-2">Mode Lingkungan</label>
            <div className="flex gap-2">
              {[{ v: false, label: 'Sandbox (Testing)' }, { v: true, label: 'Production' }].map(opt => (
                <button key={String(opt.v)} type="button"
                  onClick={() => setForm(f => ({ ...f, is_production: opt.v }))}
                  className={`flex-1 py-2 text-sm rounded-xl border font-medium transition-colors ${
                    form.is_production === opt.v
                      ? 'bg-[#ed6f5c] text-white border-[#ed6f5c]'
                      : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                  }`}>
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          {/* API Key */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1">
              {meta.apiKeyLabel} {existingData?.api_key_masked && <span className="text-xs text-gray-400 font-normal">(saat ini: {existingData.api_key_masked})</span>}
            </label>
            <div className="relative">
              <input
                type={showKey ? 'text' : 'password'}
                value={form.api_key}
                onChange={e => setForm(f => ({ ...f, api_key: e.target.value }))}
                placeholder={existingData?.api_key_masked ? 'Isi untuk mengganti key lama' : meta.apiKeyPlaceholder}
                className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c] pr-10"
              />
              <button type="button" onClick={() => setShowKey(v => !v)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 text-xs">
                {showKey ? 'Sembunyikan' : 'Tampilkan'}
              </button>
            </div>
          </div>

          {/* Extra field (Webhook Token for Xendit / Client Key for Midtrans) */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1">
              {meta.extraLabel}
              {meta.extraField === 'webhook_token' && existingData?.has_webhook_token && (
                <span className="text-xs text-gray-400 font-normal ml-1">(sudah dikonfigurasi)</span>
              )}
              {meta.extraField === 'client_key' && existingData?.has_client_key && (
                <span className="text-xs text-gray-400 font-normal ml-1">(sudah dikonfigurasi)</span>
              )}
            </label>
            <input
              type="text"
              value={meta.extraField === 'webhook_token' ? form.webhook_token : form.client_key}
              onChange={e => setForm(f => ({
                ...f,
                [meta.extraField]: e.target.value,
              }))}
              placeholder={meta.extraPlaceholder}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]"
            />
          </div>

          {/* Test connection */}
          <div>
            <button type="button" onClick={handleTest} disabled={testing}
              className="w-full flex items-center justify-center gap-2 border border-dashed border-gray-300 text-gray-600 rounded-xl py-2.5 text-sm hover:bg-gray-50 disabled:opacity-50">
              <Zap size={14} className={testing ? 'animate-pulse' : ''} />
              {testing ? 'Mengetes...' : 'Test Koneksi API Key'}
            </button>
            {testResult && (
              <div className={`mt-2 flex items-center gap-2 p-3 rounded-lg text-sm ${
                testResult.success ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'
              }`}>
                {testResult.success ? <CheckCircle size={14} /> : <AlertTriangle size={14} />}
                {testResult.message}
              </div>
            )}
          </div>

          <div className="flex gap-2 pt-1">
            {existingData?.id && (
              <button type="button" onClick={handleDelete} disabled={deleting}
                className="px-3 py-2.5 border border-red-200 text-red-500 rounded-xl text-sm hover:bg-red-50 disabled:opacity-50">
                Hapus
              </button>
            )}
            <button type="button" onClick={onClose}
              className="flex-1 border border-gray-200 text-gray-600 rounded-xl py-2.5 text-sm font-semibold hover:bg-gray-50">
              Batal
            </button>
            <button type="submit" disabled={saving}
              className="flex-1 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan Konfigurasi'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

// ── Create Payment Link Modal ──────────────────────────────────────────────────
function CreatePaymentLinkModal({ open, onClose, onCreated, gateways, invoices, tenants, preselectedInvoice }) {
  const [invoiceId, setInvoiceId]  = useState('');
  const [gateway, setGateway]      = useState('');
  const [saving, setSaving]        = useState(false);
  const [error, setError]          = useState('');
  const [result, setResult]        = useState(null);

  const activeGateways = (gateways || []).filter(g => g.is_active);

  useEffect(() => {
    if (open) {
      setInvoiceId(preselectedInvoice?.id || '');
      setGateway(activeGateways[0]?.provider || '');
      setError(''); setResult(null); setSaving(false);
    }
  }, [open, preselectedInvoice]);

  const tenantMap = Object.fromEntries((tenants || []).map(t => [t.id, t.name]));

  const selectedInv = invoices.find(i => i.id === invoiceId);

  const handleGenerate = async () => {
    if (!invoiceId) { setError('Pilih invoice'); return; }
    if (!gateway)   { setError('Pilih gateway'); return; }
    setSaving(true); setError('');
    try {
      const res  = await fetch(`${API_BASE_URL}/api/vendor/payment-link`, {
        method: 'POST', headers: hdrs(),
        body: JSON.stringify({ invoice_id: invoiceId, gateway }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal membuat link');
      setResult(data);
      onCreated();
    } catch (err) { setError(err.message); }
    setSaving(false);
  };

  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-[#fdf1ef] rounded-lg flex items-center justify-center">
              <Link2 size={15} className="text-[#ed6f5c]" />
            </div>
            <h3 className="font-bold text-gray-800">Buat Link Pembayaran</h3>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>

        <div className="p-5 space-y-4">
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          )}

          {result ? (
            <div className="space-y-4">
              <div className="text-center py-2">
                <div className="w-12 h-12 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-3">
                  <CheckCircle size={24} className="text-emerald-600" />
                </div>
                <p className="font-semibold text-gray-800">Link Pembayaran Berhasil Dibuat</p>
                <p className="text-sm text-gray-500 mt-1">{result.invoice_number} · {fmt(result.amount)}</p>
              </div>
              <div className="bg-gray-50 rounded-xl p-3">
                <p className="text-xs text-gray-400 mb-1.5">Payment URL</p>
                <p className="text-xs font-mono text-gray-700 break-all leading-relaxed mb-2">
                  {result.payment_url}
                </p>
                <div className="flex gap-2">
                  <CopyButton text={result.payment_url} label="Salin URL" />
                  <a href={result.payment_url} target="_blank" rel="noopener noreferrer"
                    className="flex items-center gap-1 px-2 py-1 text-xs text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-50">
                    <ExternalLink size={12} /> Buka
                  </a>
                </div>
              </div>
              <button onClick={onClose}
                className="w-full bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold hover:bg-[#e05544]">
                Selesai
              </button>
            </div>
          ) : (
            <>
              {activeGateways.length === 0 && (
                <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 text-sm text-amber-700">
                  Belum ada gateway aktif. Aktifkan Xendit atau Midtrans dulu.
                </div>
              )}

              <div>
                <label className="text-sm font-medium text-gray-700 block mb-1">Invoice *</label>
                <select value={invoiceId} onChange={e => setInvoiceId(e.target.value)}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]">
                  <option value="">-- Pilih Invoice --</option>
                  {invoices.filter(i => i.status === 'unpaid' || i.status === 'overdue').map(i => (
                    <option key={i.id} value={i.id}>
                      {i.invoice_number} — {i.tenant_name || tenantMap[i.tenant_id] || '-'} ({fmt(i.amount)})
                    </option>
                  ))}
                </select>
              </div>

              {selectedInv && (
                <div className="bg-gray-50 rounded-xl p-3 text-sm">
                  <div className="flex justify-between text-gray-600">
                    <span>Tenant</span><span className="font-medium text-gray-800">{selectedInv.tenant_name || '-'}</span>
                  </div>
                  <div className="flex justify-between text-gray-600 mt-1">
                    <span>Jumlah</span><span className="font-bold text-gray-800">{fmt(selectedInv.amount)}</span>
                  </div>
                </div>
              )}

              <div>
                <label className="text-sm font-medium text-gray-700 block mb-2">Gateway *</label>
                <div className="flex gap-2">
                  {activeGateways.map(g => (
                    <button key={g.provider} type="button"
                      onClick={() => setGateway(g.provider)}
                      className={`flex-1 py-2.5 text-sm rounded-xl border font-medium transition-colors ${
                        gateway === g.provider
                          ? 'bg-[#ed6f5c] text-white border-[#ed6f5c]'
                          : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                      }`}>
                      {GATEWAY_META[g.provider]?.name || g.provider}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-2 pt-1">
                <button onClick={onClose}
                  className="flex-1 border border-gray-200 text-gray-600 rounded-xl py-2.5 text-sm font-semibold hover:bg-gray-50">
                  Batal
                </button>
                <button onClick={handleGenerate} disabled={saving || activeGateways.length === 0}
                  className="flex-1 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
                  {saving ? 'Memproses...' : 'Generate Link'}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

