import { useEffect, useState } from "react";
import { createPortal } from 'react-dom';
import { API_BASE_URL } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { toast } from "@/components/ui/sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogFooter,
  AlertDialogCancel,
  AlertDialogAction,
} from "@/components/ui/alert-dialog";
import { FileImage } from "lucide-react";
import sorrySvg from "@/assets/images/sorry.svg";

const BANSOS_OPTIONS = ["Ya", "Tidak"];

const EMPTY_FORM = {
  rumah_id: "",
  nomor_kk: "",
  provinsi: "",
  kabupaten: "",
  kecamatan: "",
  kelurahan: "",
  nomor_rt: 0,
  nomor_rw: 0,
  nama_desa: "",
  status_kesejahteraan: "",
  aktif: true,
};

export default function KartuKeluargaPage() {
  const { token, logout, user } = useAuth();
  const { canCreate, canUpdate, canDelete } = useRolePermissions(user?.role, token);

  const [kkList, setKkList] = useState([]);
  const [rumahList, setRumahList] = useState([]);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);

  const [openForm, setOpenForm] = useState(false);
  const [selectedKK, setSelectedKK] = useState(null);
  const [formData, setFormData] = useState(EMPTY_FORM);
  const [saving, setSaving] = useState(false);

  const [deleteTarget, setDeleteTarget] = useState(null);

  const [uploadFile, setUploadFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [fotoTs, setFotoTs] = useState(Date.now());
  const [lightboxKK, setLightboxKK] = useState(null);

  const authHeaders = { Authorization: `Bearer ${token}` };

  const loadKK = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kartu-keluarga`, { headers: authHeaders });
      if (res.status === 401) { logout(); return; }
      const data = await res.json();
      setKkList(data);
    } catch {
      toast.error("Gagal memuat data Kartu Keluarga");
    }
  };

  const loadRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, { headers: authHeaders });
      if (res.ok) setRumahList(await res.json());
    } catch {
      // non-critical
    }
  };

  useEffect(() => {
    loadKK();
    loadRumah();
  }, []);

  const openAddForm = () => {
    setSelectedKK(null);
    setFormData(EMPTY_FORM);
    setUploadFile(null);
    setOpenForm(true);
  };

  const openEditForm = (kk) => {
    setSelectedKK(kk);
    setFormData({
      rumah_id: kk.rumah_id || "",
      nomor_kk: kk.nomor_kk || "",
      provinsi: kk.provinsi || "",
      kabupaten: kk.kabupaten || "",
      kecamatan: kk.kecamatan || "",
      kelurahan: kk.kelurahan || "",
      nomor_rt: kk.nomor_rt ?? 0,
      nomor_rw: kk.nomor_rw ?? 0,
      nama_desa: kk.nama_desa || "",
      status_kesejahteraan: kk.status_kesejahteraan || "",
      aktif: kk.aktif ?? true,
    });
    setUploadFile(null);
    setOpenForm(true);
  };

  const handleSave = async () => {
    if (!formData.nomor_kk.trim()) {
      toast.error("Nomor KK wajib diisi");
      return;
    }
    setSaving(true);
    try {
      const payload = {
        ...formData,
        rumah_id: formData.rumah_id || null,
        status_kesejahteraan: formData.status_kesejahteraan || null,
        nomor_rt: Number(formData.nomor_rt) || 0,
        nomor_rw: Number(formData.nomor_rw) || 0,
      };

      let savedId = selectedKK?.id;

      if (selectedKK) {
        const res = await fetch(`${API_BASE_URL}/api/kartu-keluarga/${selectedKK.id}`, {
          method: "PUT",
          headers: { ...authHeaders, "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
        if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          toast.error(err.detail || "Gagal mengupdate Kartu Keluarga");
          return;
        }
      } else {
        const res = await fetch(`${API_BASE_URL}/api/kartu-keluarga`, {
          method: "POST",
          headers: { ...authHeaders, "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
        if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          toast.error(err.detail || "Gagal menambah Kartu Keluarga");
          return;
        }
        const created = await res.json();
        savedId = created.id;
      }

      toast.success(selectedKK ? "Kartu Keluarga diperbarui" : "Kartu Keluarga ditambahkan");
      setOpenForm(false);
      loadKK();
    } finally {
      setSaving(false);
    }
  };

  const handleUploadFoto = async () => {
    if (!uploadFile || !selectedKK) return;
    setUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", uploadFile);
      const res = await fetch(`${API_BASE_URL}/api/kartu-keluarga/${selectedKK.id}/upload-foto`, {
        method: "POST",
        headers: authHeaders,
        body: fd,
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        toast.error(err.detail || "Gagal upload foto KK");
        return;
      }
      const result = await res.json();
      setSelectedKK({ ...selectedKK, foto_kk: result.foto_kk });
      setFotoTs(Date.now());
      setUploadFile(null);
      toast.success("Foto KK berhasil diupload");
      loadKK();
    } catch (e) {
      toast.error("Gagal upload foto: " + e.message);
    } finally {
      setUploading(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/kartu-keluarga/${deleteTarget.id}`, {
        method: "DELETE",
        headers: authHeaders,
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        toast.error(err.detail || "Gagal menghapus Kartu Keluarga");
        return;
      }
      toast.success("Kartu Keluarga berhasil dihapus");
      loadKK();
    } finally {
      setDeleteTarget(null);
    }
  };

  const filtered = kkList.filter((kk) => {
    const q = search.toLowerCase();
    return (
      kk.nomor_kk?.toLowerCase().includes(q) ||
      kk.blok_no?.toLowerCase().includes(q) ||
      kk.nama_desa?.toLowerCase().includes(q)
    );
  });

  const totalPages = Math.ceil(filtered.length / perPage);
  const paginated = filtered.slice((page - 1) * perPage, page * perPage);

  const field = (label, key, type = "text", extra = {}) => (
    <div className="space-y-1">
      <Label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">{label}</Label>
      <Input
        type={type}
        value={formData[key]}
        onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
        className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        {...extra}
      />
    </div>
  );

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Kartu Keluarga</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">Kelola data Kartu Keluarga warga</p>
        </div>
        {canCreate("kartu-keluarga") && (
          <Button onClick={openAddForm} className="bg-[#ed6f5c] hover:bg-[#e05544] text-white">
            + Tambah KK
          </Button>
        )}
      </div>

      {/* SEARCH & PER PAGE */}
      <div className="flex gap-3 items-center">
        <Input
          placeholder="Cari nomor KK, blok, atau nama desa..."
          value={search}
          onChange={(e) => { setSearch(e.target.value); setPage(1); }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <select
          value={perPage}
          onChange={(e) => { setPerPage(Number(e.target.value)); setPage(1); }}
          className="p-2 border rounded-md text-sm dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-white"
        >
          {[10, 25, 50].map((n) => (
            <option key={n} value={n}>{n} / hal</option>
          ))}
        </select>
      </div>

      {/* TABLE */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700 overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b dark:border-gray-700 bg-[#ece4cf] dark:bg-gray-800 text-left">
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Rumah</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Foto KK</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Nomor KK</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Provinsi</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Kabupaten</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Kecamatan</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Kelurahan</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">RT</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">RW</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Nama Desa</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Bantuan Sosial</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Aktif</th>
              <th className="px-3 py-3 font-semibold text-gray-700 dark:text-gray-300">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {paginated.length === 0 ? (
              <tr>
                <td colSpan={13}>
                  <div className="flex flex-col items-center justify-center py-12 gap-3">
                    <img src={sorrySvg} alt="Tidak ada data" className="w-32 h-32 opacity-70" />
                    <p className="text-gray-400 dark:text-gray-600 text-sm">Belum ada data Kartu Keluarga</p>
                  </div>
                </td>
              </tr>
            ) : (
              paginated.map((kk) => (
                <tr key={kk.id} className="border-b dark:border-gray-800 hover:bg-[#ece4cf]/50 dark:hover:bg-gray-800/50">
                  <td className="px-3 py-2 font-medium text-gray-800 dark:text-gray-200">{kk.blok_no || "—"}</td>
                  <td className="px-3 py-2">
                    {kk.foto_kk ? (
                      <img
                        src={`${API_BASE_URL}/api/kartu-keluarga/${kk.id}/foto`}
                        alt="KK"
                        className="w-10 h-10 object-cover rounded border dark:border-gray-700 cursor-pointer hover:opacity-80 hover:scale-110 transition-transform"
                        onClick={() => setLightboxKK(kk)}
                        onError={(e) => { e.target.style.display = "none"; }}
                      />
                    ) : (
                      <span className="inline-flex items-center justify-center w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded border dark:border-gray-700 text-gray-400">
                        <FileImage size={18} />
                      </span>
                    )}
                  </td>
                  <td className="px-3 py-2 text-gray-700 dark:text-gray-300 font-mono">{kk.nomor_kk}</td>
                  <td className="px-3 py-2 text-gray-600 dark:text-gray-400">{kk.provinsi || "—"}</td>
                  <td className="px-3 py-2 text-gray-600 dark:text-gray-400">{kk.kabupaten || "—"}</td>
                  <td className="px-3 py-2 text-gray-600 dark:text-gray-400">{kk.kecamatan || "—"}</td>
                  <td className="px-3 py-2 text-gray-600 dark:text-gray-400">{kk.kelurahan || "—"}</td>
                  <td className="px-3 py-2 text-center text-gray-600 dark:text-gray-400">{kk.nomor_rt}</td>
                  <td className="px-3 py-2 text-center text-gray-600 dark:text-gray-400">{kk.nomor_rw}</td>
                  <td className="px-3 py-2 text-gray-600 dark:text-gray-400">{kk.nama_desa || "—"}</td>
                  <td className="px-3 py-2">
                    {kk.status_kesejahteraan === "Ya" ? (
                      <span className="inline-block px-2 py-0.5 rounded-full text-xs font-semibold bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">Ya</span>
                    ) : kk.status_kesejahteraan === "Tidak" ? (
                      <span className="inline-block px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400">Tidak</span>
                    ) : (
                      <span className="text-gray-400">—</span>
                    )}
                  </td>
                  <td className="px-3 py-2">
                    <span className={`inline-block px-2 py-0.5 rounded-full text-xs font-semibold ${kk.aktif ? "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400" : "bg-gray-200 text-gray-500 dark:bg-gray-700 dark:text-gray-400"}`}>
                      {kk.aktif ? "Aktif" : "Nonaktif"}
                    </span>
                  </td>
                  <td className="px-3 py-2">
                    <div className="flex gap-1">
                      {canUpdate("kartu-keluarga") && (
                        <Button size="sm" variant="outline" onClick={() => openEditForm(kk)}
                          className="h-7 px-2 dark:border-gray-700 dark:text-gray-300">
                          ✏️
                        </Button>
                      )}
                      {canDelete("kartu-keluarga") && (
                        <Button size="sm" variant="outline" onClick={() => setDeleteTarget(kk)}
                          className="h-7 px-2 border-red-200 text-red-600 hover:bg-red-50 dark:border-red-800 dark:text-red-400">
                          🗑️
                        </Button>
                      )}
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* PAGINATION */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {filtered.length === 0
            ? "Tidak ada data"
            : `${(page - 1) * perPage + 1}–${Math.min(page * perPage, filtered.length)} dari ${filtered.length}`}
        </span>
        <div className="flex gap-2">
          <Button size="sm" variant="outline" onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1} className="dark:border-gray-700 dark:text-gray-200">
            Sebelumnya
          </Button>
          <Button size="sm" variant="outline" onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page >= totalPages} className="dark:border-gray-700 dark:text-gray-200">
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent className="max-w-2xl bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100 max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{selectedKK ? "Edit Kartu Keluarga" : "Tambah Kartu Keluarga"}</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            {/* Rumah */}
            <div className="space-y-1">
              <Label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Rumah</Label>
              <select
                value={formData.rumah_id}
                onChange={(e) => setFormData({ ...formData, rumah_id: e.target.value })}
                className="w-full p-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf] text-sm"
              >
                <option value="">— Pilih Rumah (opsional) —</option>
                {rumahList.map((r) => (
                  <option key={r.id} value={r.id}>{r.blok_no}</option>
                ))}
              </select>
            </div>

            {/* Nomor KK */}
            <div className="space-y-1">
              <Label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nomor KK <span className="text-red-500">*</span></Label>
              <Input
                value={formData.nomor_kk}
                onChange={(e) => setFormData({ ...formData, nomor_kk: e.target.value.replace(/\D/g, "").slice(0, 16) })}
                placeholder="16 digit nomor KK"
                maxLength={16}
                className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700 font-mono"
              />
            </div>

            {/* Wilayah 2 kolom */}
            <div className="grid grid-cols-2 gap-3">
              {field("Provinsi", "provinsi")}
              {field("Kabupaten / Kota", "kabupaten")}
              {field("Kecamatan", "kecamatan")}
              {field("Kelurahan / Desa", "kelurahan")}
            </div>

            {/* RT RW Nama Desa */}
            <div className="grid grid-cols-3 gap-3">
              {field("Nomor RT", "nomor_rt", "number")}
              {field("Nomor RW", "nomor_rw", "number")}
              {field("Nama Desa", "nama_desa")}
            </div>

            {/* Bantuan Sosial */}
            <div className="space-y-1">
              <Label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Bantuan Sosial</Label>
              <select
                value={formData.status_kesejahteraan}
                onChange={(e) => setFormData({ ...formData, status_kesejahteraan: e.target.value })}
                className="w-full p-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf] text-sm"
              >
                <option value="">— Pilih —</option>
                {BANSOS_OPTIONS.map((s) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </div>

            {/* Aktif */}
            <div className="flex items-center gap-3">
              <Switch
                checked={formData.aktif}
                onCheckedChange={(v) => setFormData({ ...formData, aktif: v })}
              />
              <Label className="text-sm dark:text-gray-300">Aktif</Label>
            </div>

            {/* Upload Foto — hanya saat edit */}
            {selectedKK && (
              <div className="space-y-3 border-t dark:border-gray-700 pt-4">
                <Label className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Foto KK</Label>
                {selectedKK.foto_kk ? (
                  <img
                    src={`${API_BASE_URL}/api/kartu-keluarga/${selectedKK.id}/foto?t=${fotoTs}`}
                    alt="Foto KK"
                    className="h-28 rounded border dark:border-gray-700 object-cover"
                    onError={(e) => { e.target.style.display = "none"; }}
                  />
                ) : (
                  <div className="flex items-center gap-2 text-gray-400 text-sm">
                    <FileImage size={20} />
                    <span>Belum ada foto</span>
                  </div>
                )}
                <div className="flex gap-2 items-center">
                  <Input
                    type="file"
                    accept=".jpg,.jpeg,.png,.webp"
                    onChange={(e) => setUploadFile(e.target.files[0] || null)}
                    className="flex-1 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300"
                  />
                  <Button
                    type="button"
                    onClick={handleUploadFoto}
                    disabled={!uploadFile || uploading}
                    className="bg-blue-600 hover:bg-blue-700 text-white shrink-0"
                  >
                    {uploading ? "Mengupload..." : "Upload Foto"}
                  </Button>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400">Format: JPG, PNG, WEBP. Klik "Upload Foto" setelah memilih file.</p>
              </div>
            )}
          </div>

          <DialogFooter className="gap-2">
            <Button variant="outline" onClick={() => setOpenForm(false)}
              className="dark:border-gray-700 dark:text-gray-200">
              Batal
            </Button>
            <Button onClick={handleSave} disabled={saving || uploading}
              className="bg-[#ed6f5c] hover:bg-[#e05544] text-white">
              {saving || uploading ? "Menyimpan..." : selectedKK ? "Simpan Perubahan" : "Tambah KK"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* LIGHTBOX FOTO */}
      {lightboxKK && createPortal(
        <div
          className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80"
          onClick={() => setLightboxKK(null)}
        >
          <div className="relative max-w-3xl w-full mx-4" onClick={(e) => e.stopPropagation()}>
            <button
              onClick={() => setLightboxKK(null)}
              className="absolute -top-10 right-0 text-white text-3xl font-bold hover:text-gray-300 leading-none"
            >
              &times;
            </button>
            <div className="bg-white dark:bg-gray-900 rounded-xl overflow-hidden shadow-2xl">
              <div className="p-3 border-b dark:border-gray-700 flex items-center justify-between">
                <span className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                  Foto KK — {lightboxKK.nomor_kk}
                </span>
                <span className="text-xs text-gray-400">{lightboxKK.blok_no}</span>
              </div>
              <img
                src={`${API_BASE_URL}/api/kartu-keluarga/${lightboxKK.id}/foto`}
                alt={`KK ${lightboxKK.nomor_kk}`}
                className="w-full max-h-[75vh] object-contain bg-gray-100 dark:bg-gray-800"
              />
            </div>
          </div>
        </div>,
        document.body
      )}

      {/* DELETE DIALOG */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(v) => !v && setDeleteTarget(null)}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Kartu Keluarga?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Nomor KK <strong>{deleteTarget?.nomor_kk}</strong> akan dihapus secara permanen.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700 text-white">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
