import React, { useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { useAuth } from '@/contexts/AuthContext';
import { API_ENDPOINTS } from '@/config/api';
import { toast } from 'sonner';

export default function BudgetIncomeForm({ open, onClose, onSuccess }) {
    const { token } = useAuth();
    const [categories, setCategories] = useState([]);
    const [formData, setFormData] = useState({
        finance_category_id: '',
        jumlah: '',
        keterangan: '',
        tanggal: new Date().toISOString().split('T')[0]
    });
    const [loading, setLoading] = useState(false);

    // Load categories
    useEffect(() => {
        if (open) {
            loadCategories();
            setFormData({
                finance_category_id: '',
                jumlah: '',
                keterangan: '',
                tanggal: new Date().toISOString().split('T')[0]
            });
        }
    }, [open, token]);

    const loadCategories = async () => {
        try {
            const res = await fetch(API_ENDPOINTS.FINANCE_CATEGORY, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                // Filter pemasukan only? User requirement: "Pilih POS (finance_category)... Transaksi bertipe pemasukan"
                // Make sense.
                const data = await res.json();
                setCategories(data); // Show ALL because maybe user wants to fund "Gaji Security" (Expense pos) with Income?
                // But usually Income goes to Income Categories (e.g. Funding, Sumbangan).
                // Then Budget consumes from General Cash.
                // Let's show all categories just in case. Or sort/group.
            }
        } catch (err) {
            console.error(err);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const payload = {
                finance_category_id: formData.finance_category_id,
                jumlah: parseFloat(formData.jumlah),
                keterangan: formData.keterangan,
                tanggal: new Date(formData.tanggal).toISOString()
            };

            const res = await fetch(API_ENDPOINTS.BUDGET_INPUT_DANA, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(payload)
            });

            if (!res.ok) {
                const errData = await res.json().catch(() => ({}));
                throw new Error(errData.detail || 'Gagal mencatat transaksi');
            }

            toast.success(`Dana berhasil dicatat ke Keuangan`);
            onSuccess(); // Refresh Budget Overview (if realization depends on it... unlikely if realization=expense)
            onClose();

        } catch (error) {
            toast.error(error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle>Input Transaksi Dana (Pemasukan)</DialogTitle>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-4 py-4">
                    <div className="space-y-2">
                        <Label>Pos Keuangan / Kategori</Label>
                        <Select
                            value={formData.finance_category_id}
                            onValueChange={(val) => setFormData({ ...formData, finance_category_id: val })}
                            required
                        >
                            <SelectTrigger>
                                <SelectValue placeholder="Pilih Pos..." />
                            </SelectTrigger>
                            <SelectContent>
                                {categories.map(cat => (
                                    <SelectItem key={cat.id} value={cat.id}>
                                        {cat.nama} <span className="text-gray-400 text-xs">({cat.tipe})</span>
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Tanggal</Label>
                            <Input
                                type="date"
                                value={formData.tanggal}
                                onChange={(e) => setFormData({ ...formData, tanggal: e.target.value })}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Jumlah Pemasukan</Label>
                            <div className="relative">
                                <span className="absolute left-3 top-2.5 text-gray-500 text-sm">Rp</span>
                                <Input
                                    type="text"
                                    className="pl-9"
                                    value={formData.jumlah ? parseFloat(formData.jumlah.toString().replace(/\./g, '')).toLocaleString('id-ID') : ''}
                                    onChange={(e) => {
                                        const value = e.target.value.replace(/\D/g, '');
                                        setFormData({ ...formData, jumlah: value });
                                    }}
                                    placeholder="1.000.000"
                                    required
                                />
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Keterangan</Label>
                        <Textarea
                            placeholder="Contoh: Dana tambahan dari donator"
                            value={formData.keterangan}
                            onChange={(e) => setFormData({ ...formData, keterangan: e.target.value })}
                        />
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={onClose}>Batal</Button>
                        <Button type="submit" disabled={loading} className="bg-green-600 hover:bg-green-700">
                            {loading ? 'Menyimpan...' : 'Simpan Pemasukan'}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}
