// ── Reusable editor primitives ─────────────────────────────────────────────
const Label = ({ children, hint }) => (
  <div className="mb-1.5">
    <label className="text-xs font-semibold text-gray-700 uppercase tracking-wide">{children}</label>
    {hint && <p className="text-xs text-gray-400 mt-0.5 normal-case font-normal">{hint}</p>}
  </div>
);

const TextField = ({ value, onChange, placeholder, mono = false }) => (
  <input type="text" value={value || ''} onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    className={`w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c] ${mono ? 'font-mono text-xs' : ''}`} />
);

const TextArea = ({ value, onChange, placeholder, rows = 3 }) => (
  <textarea value={value || ''} onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder} rows={rows}
    className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]" />
);

// Field with label + input combined
const Field = ({ label, hint, children }) => (
  <div className="space-y-1">
    <Label hint={hint}>{label}</Label>
    {children}
  </div>
);

// Link {label, href} pair editor
const LinkPair = ({ value = {}, onChange }) => (
  <div className="grid grid-cols-2 gap-2">
    <TextField value={value.label} onChange={(v) => onChange({ ...value, label: v })} placeholder="Label" />
    <TextField value={value.href}  onChange={(v) => onChange({ ...value, href: v })}  placeholder="#href" mono />
  </div>
);

// Add/Remove array editor — children(item, idx, setItem) renders one card
const ItemList = ({ items, onChange, newItem, label, children, collapsedKey }) => {
  const [openIdx, setOpenIdx] = useState(0);
  const setItem = (idx) => (next) => {
    const arr = [...items];
    arr[idx] = next;
    onChange(arr);
  };
  const add = () => {
    onChange([...items, typeof newItem === 'function' ? newItem() : newItem]);
    setOpenIdx(items.length);
  };
  const remove = (idx) => {
    if (!window.confirm('Hapus item ini?')) return;
    onChange(items.filter((_, i) => i !== idx));
  };
  return (
    <div className="space-y-2">
      {items.map((it, idx) => {
        const isOpen = openIdx === idx;
        const summary = it[collapsedKey] || `Item ${idx + 1}`;
        return (
          <div key={idx} className="border border-gray-200 rounded-lg overflow-hidden bg-white">
            <button onClick={() => setOpenIdx(isOpen ? -1 : idx)}
              className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-50 transition-colors">
              <div className="flex items-center gap-2 min-w-0">
                {isOpen ? <ChevronDown size={14} className="text-gray-400" /> : <ChevronRight size={14} className="text-gray-400" />}
                <span className="text-sm font-medium text-gray-700 truncate" dangerouslySetInnerHTML={{ __html: summary }} />
              </div>
              <span onClick={(e) => { e.stopPropagation(); remove(idx); }}
                className="text-red-400 hover:text-red-600 cursor-pointer p-1 rounded hover:bg-red-50">
                <Trash2 size={13} />
              </span>
            </button>
            {isOpen && (
              <div className="p-3 border-t border-gray-100 space-y-3 bg-gray-50/30">
                {children(it, idx, setItem(idx))}
              </div>
            )}
          </div>
        );
      })}
      <button onClick={add}
        className="w-full py-2 border border-dashed border-gray-300 rounded-lg text-sm text-gray-500 hover:border-[#ed6f5c] hover:text-[#ed6f5c] transition-colors flex items-center justify-center gap-1.5">
        <Plus size={13} /> Tambah {label}
      </button>
    </div>
  );
};

