// ── Main Component ─────────────────────────────────────────────────────────
export default function VendorCMS() {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving,  setSaving]  = useState(false);
  const [error,   setError]   = useState(null);
  const [notice,  setNotice]  = useState(null);
  const [tab,     setTab]     = useState('nav');

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const res = await fetch(`${API_BASE_URL}/api/cms/landing`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      setContent(data);
    } catch (e) {
      setError(e.message || 'Gagal memuat konten');
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const save = async () => {
    setSaving(true); setError(null); setNotice(null);
    try {
      const res = await fetch(`${API_BASE_URL}/api/cms/landing`, {
        method: 'PUT', headers: hdrs(), body: JSON.stringify(content),
      });
      if (!res.ok) {
        let detail = `HTTP ${res.status}`;
        try { const j = await res.json(); detail = j.detail || detail; } catch (_) {}
        throw new Error(detail);
      }
      const data = await res.json();
      setContent(data);
      setNotice('Konten berhasil disimpan.');
      setTimeout(() => setNotice(null), 3000);
    } catch (e) {
      setError(e.message || 'Gagal menyimpan');
    } finally { setSaving(false); }
  };

  const resetDefault = async () => {
    if (!window.confirm('Reset semua konten ke default? Perubahan yang sudah disimpan akan hilang.')) return;
    setSaving(true); setError(null);
    try {
      const res = await fetch(`${API_BASE_URL}/api/cms/landing`, { method: 'DELETE', headers: hdrs() });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      setContent(data);
      setNotice('Konten direset ke default.');
      setTimeout(() => setNotice(null), 3000);
    } catch (e) {
      setError(e.message || 'Gagal reset');
    } finally { setSaving(false); }
  };

  const setSection = (key) => (next) => setContent({ ...content, [key]: next });

  if (loading) return (
    <div className="flex items-center justify-center py-20">
      <div className="text-center space-y-3">
        <div className="w-10 h-10 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin mx-auto" />
        <p className="text-sm text-gray-500">Memuat konten CMS...</p>
      </div>
    </div>
  );

  if (!content) return (
    <div className="bg-red-50 border border-red-200 rounded-xl p-5 flex items-start gap-3">
      <AlertCircle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
      <div>
        <p className="font-medium text-red-700">Gagal memuat konten</p>
        <p className="text-sm text-red-600 mt-1">{error}</p>
        <button onClick={load} className="mt-2 text-sm text-red-600 underline">Coba lagi</button>
      </div>
    </div>
  );

  const Editor = EDITORS[tab];
  const sectionData = content[tab] || {};

  return (
    <div className="max-w-5xl mx-auto space-y-5">
      {/* Header */}
      <div className="bg-white rounded-2xl border border-gray-200 p-5 flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-[#fdf1ef] rounded-xl flex items-center justify-center">
            <FileText size={18} className="text-[#ed6f5c]" />
          </div>
          <div>
            <h1 className="text-lg font-bold text-gray-900">CMS Landing Page</h1>
            <p className="text-xs text-gray-500">Kelola teks, paket harga, FAQ, dan kalimat pada halaman publik</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <a href="/" target="_blank" rel="noreferrer"
            className="flex items-center gap-1.5 px-3 py-2 text-sm border border-gray-200 text-gray-600 rounded-lg hover:bg-gray-50 transition-colors">
            <ExternalLink size={13} /> Pratinjau
          </a>
          <button onClick={resetDefault} disabled={saving}
            className="flex items-center gap-1.5 px-3 py-2 text-sm border border-gray-200 text-gray-600 rounded-lg hover:bg-gray-50 disabled:opacity-50 transition-colors">
            <RotateCcw size={13} /> Reset Default
          </button>
          <button onClick={save} disabled={saving}
            className="flex items-center gap-1.5 px-4 py-2 text-sm bg-[#ed6f5c] hover:bg-[#d95d4c] text-white rounded-lg disabled:opacity-60 transition-colors">
            {saving ? <RefreshCw size={13} className="animate-spin" /> : <Save size={13} />}
            {saving ? 'Menyimpan...' : 'Simpan'}
          </button>
        </div>
      </div>

      {/* Notice/Error */}
      {notice && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-3 flex items-center gap-2 text-sm text-emerald-700">
          <CheckCircle size={15} /> {notice}
        </div>
      )}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-xl p-3 flex items-center gap-2 text-sm text-red-700">
          <AlertCircle size={15} /> {error}
        </div>
      )}

      {/* Tabs */}
      <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
        <div className="flex border-b border-gray-200 overflow-x-auto">
          {SECTIONS.map((s) => (
            <button key={s.key} onClick={() => setTab(s.key)}
              className={`px-4 py-3 text-sm font-medium whitespace-nowrap border-b-2 -mb-px transition-colors ${
                tab === s.key
                  ? 'border-[#ed6f5c] text-[#ed6f5c] bg-[#fdf1ef]/40'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
              }`}>
              {s.label}
            </button>
          ))}
        </div>
        <div className="p-5">
          {Editor && <Editor data={sectionData} set={setSection(tab)} />}
        </div>
      </div>

      {/* Footer save */}
      <div className="flex justify-end">
        <button onClick={save} disabled={saving}
          className="flex items-center gap-1.5 px-4 py-2 text-sm bg-[#ed6f5c] hover:bg-[#d95d4c] text-white rounded-lg disabled:opacity-60 transition-colors">
          {saving ? <RefreshCw size={13} className="animate-spin" /> : <Save size={13} />}
          {saving ? 'Menyimpan...' : 'Simpan Perubahan'}
        </button>
      </div>
    </div>
  );
}
